// Üretilen dosya: tool/ozgun/uret.py. Matematik · İkinci dereceden denklemler ve eşitsizlikler (orta).
const ozMathematics9Orta = <(String, String, List<String>, String)>[
  ('Aşağıdaki eşitliklerden hangisi düzenlendiğinde ikinci dereceden bir denklem olmaz?', '(x + 1)² = x² + 4', ['x(x − 2) = 5', '2x² = 7x', '(x − 3)(x + 1) = 0'], '(x + 1)² = x² + 4 açılınca x² terimleri sadeleşir ve 2x − 3 = 0 gibi birinci dereceden bir denklem kalır. Diğerlerinde x² terimi korunur.'),
  ('2x² − 7x + 5 = 0 denkleminde katsayıların toplamı sıfırdır. Bu gözlemden yararlanılırsa denklemin kökleri hangileri bulunur?', '1 ve 5/2', ['−1 ve −5/2', '1 ve 2/5', '−1 ve 5/2'], 'a + b + c = 0 ise x = 1 bir köktür. Kökler çarpımı c/a = 5/2 olduğundan diğer kök 5/2\'dir.'),
  ('3x² − 10x − 8 = 0 denkleminin kökleri hangileridir?', '4 ve −2/3', ['−4 ve 2/3', '4 ve 2/3', '−2 ve −4/3'], 'İfade (3x + 2)(x − 4) biçiminde çarpanlarına ayrılır. Çarpanlar sıfıra eşitlenince x = 4 ve x = −2/3 bulunur.'),
  ('Bir öğrenci (x − 2)(x − 3) = 2 denklemini x − 2 = 2 veya x − 3 = 2 yazarak çözüyor. Denklemin gerçek kökleri hangileridir?', '1 ve 4', ['4 ve 5', '2 ve 3', '−1 ve −4'], 'Sıfır çarpım özelliği yalnız sağ taraf 0 iken geçerlidir. Açınca x² − 5x + 4 = 0 elde edilir; kökler 1 ve 4\'tür.'),
  ('2x² + 12x + 5 = 0 denklemi önce 2\'ye bölünüp sonra tam kareye tamamlanarak (x + 3)² = r biçimine getiriliyor. r kaçtır?', '13/2', ['23/2', '−13/2', '13'], 'Bölünce x² + 6x + 5/2 = 0 olur. (x + 3)² = 9 − 5/2 = 13/2 bulunur.'),
  ('3x² + 2x − 2 = 0 denkleminin kökleri kök formülüyle bulunduğunda hangi sonuç elde edilir?', '(−1 ± √7)/3', ['(1 ± √7)/3', '(−1 ± √7)/6', '(−2 ± √14)/3'], 'Δ = 4 + 24 = 28, √28 = 2√7\'dir. x = (−2 ± 2√7)/6 = (−1 ± √7)/3 olur.'),
  ('x\'in katsayısı çift olan denklemlerde Δ\' = b\'² − ac (b\' = b/2) kısaltması kullanılır. x² − 8x + 3 = 0 için Δ\' kaçtır?', '13', ['52', '61', '19'], 'b\' = −4 olduğundan Δ\' = 16 − 3 = 13\'tür. Bu değer Δ = 52\'nin dörtte biridir.'),
  ('ax² + bx + c = 0 (a > 0) denkleminin iki gerçek kökü arasındaki farkın mutlak değeri hangi ifadeye eşittir?', '√Δ / a', ['√Δ / 2a', 'Δ / a', '−b / a'], 'Kökler (−b ± √Δ)/2a olduğundan farkları 2√Δ/2a = √Δ/a olur.'),
  ('Katsayıları rasyonel olan ikinci dereceden bir denklemin diskriminantı 12\'dir. Bu denklemin kökleri için hangisi doğrudur?', 'İki farklı irrasyonel kökü vardır', ['Birbirine eşit iki rasyonel kökü vardır', 'İki farklı rasyonel kökü vardır', 'Gerçek sayılarda kökü yoktur'], 'Δ > 0 olduğundan iki farklı gerçek kök vardır; 12 tam kare olmadığından √12 irrasyoneldir ve kökler irrasyonel olur.'),
  ('x² − (√2 + √3)x + √6 = 0 eşitliğini sağlayan iki gerçek sayı aşağıdakilerin hangisinde birlikte verilmiştir?', '√2 ve √3', ['−√2 ve −√3', '√2 ve −√3', '√5 ve 1'], 'Kökler toplamı √2 + √3, çarpımı √6 olan iki sayı aranır; bunlar √2 ve √3\'tür. Denklem (x − √2)(x − √3) = 0 olarak yazılabilir.'),
  ('a ve b gerçek sayılar olmak üzere (x − a)² + (x − b)² = 0 denkleminin gerçek bir kökünün bulunması için hangi koşul gereklidir?', 'a = b', ['a = −b', 'a + b = 0 ve a ≠ 0', 'ab < 0'], 'İki karenin toplamı ancak ikisi de sıfırsa sıfırdır: x = a ve x = b aynı anda olmalıdır. Bu yalnız a = b iken mümkündür.'),
  ('x² + px + q = 0 denkleminin iki farklı gerçek kökü vardır. Buna göre x² + px + q − 1 = 0 denkleminin kökleri için ne söylenebilir?', 'İki farklı gerçek kökü vardır', ['Gerçek kökü yoktur', 'Çift katlı tek kökü vardır', 'Kökleri kesinlikle negatiftir'], 'İkinci denklemin diskriminantı p² − 4(q − 1) = (p² − 4q) + 4 olup birincininkinden 4 fazladır. Birincisi pozitif olduğundan bu da pozitiftir.'),
  ('a ve b gerçek sayılar olmak üzere x² − (a + b)x + ab = 0 denkleminin diskriminantı hangi ifadeye eşittir?', '(a − b)²', ['(a + b)²', 'a² + b²', '2(a² + b²)'], 'Δ = (a + b)² − 4ab = a² − 2ab + b² = (a − b)² olur. Bu yüzden bu denklemin kökleri (a ve b) her zaman gerçektir.'),
  ('x² − 4x + 1 = 0 denkleminin kökleri x₁ ile x₂ ise küplerinin toplamı x₁³ + x₂³ kaçtır?', '52', ['64', '60', '−52'], 'x₁³ + x₂³ = (x₁ + x₂)³ − 3x₁x₂(x₁ + x₂) = 64 − 3·1·4 = 52.'),
  ('x² − 6x + 4 = 0 denkleminin kökleri x₁ ve x₂ olmak üzere x₁/x₂ + x₂/x₁ oranlar toplamının değeri nedir?', '7', ['9', '28', '3/2'], 'x₁/x₂ + x₂/x₁ = (x₁² + x₂²)/(x₁x₂) = (36 − 8)/4 = 7 bulunur.'),
  ('x² + 3x − 5 = 0 denkleminin kökleri x₁, x₂ için (x₁ − x₂)² farkının karesi kaça eşittir?', '29', ['19', '11', '−11'], '(x₁ − x₂)² = (x₁ + x₂)² − 4x₁x₂ = 9 + 20 = 29 olur; bu sayı aynı zamanda diskriminanttır.'),
  ('x² − 5x − 2 = 0 denkleminin kökleri x₁ ve x₂ ise (x₁ + 1)(x₂ + 1) çarpımı kaçtır?', '4', ['6', '−6', '2'], 'Açılım x₁x₂ + (x₁ + x₂) + 1 = −2 + 5 + 1 = 4 verir.'),
  ('x² + 4x + 2 = 0 denkleminin kökleri x₁ ve x₂ ise 1/x₁² + 1/x₂² ifadesinin değeri kaçtır?', '3', ['6', '12', '1'], '1/x₁² + 1/x₂² = (x₁² + x₂²)/(x₁x₂)² = (16 − 4)/4 = 3 olur.'),
  ('x² − 2x − 8 = 0 denkleminin köklerinin mutlak değerlerinin toplamı |x₁| + |x₂| kaçtır?', '6', ['2', '8', '10'], 'Kökler çarpımı negatif olduğundan kökler ters işaretlidir; |x₁| + |x₂| = |x₁ − x₂| = √(4 + 32) = 6 olur (kökler 4 ve −2).'),
  ('x² − 7x + 12 = 0 denkleminin kökleri x₁ > x₂ olacak biçimde adlandırılıyor. x₁² − x₂² farkı kaçtır?', '7', ['1', '25', '12'], 'x₁² − x₂² = (x₁ + x₂)(x₁ − x₂) = 7·1 = 7 bulunur.'),
  ('b bir gerçek sayı olmak üzere x² + bx − 9 = 0 denkleminin diskriminantının alabileceği en küçük değer kaçtır?', '36', ['0', '9', '−36'], 'Δ = b² + 36\'dır. b² ≥ 0 olduğundan en küçük değer b = 0 iken 36 olur.'),
  ('2x² − 5x + 3 = 0 denkleminin köklerinin çarpmaya göre tersleri, aşağıdaki denklemlerin hangisinin kökleridir?', '3x² − 5x + 2 = 0', ['2x² + 5x + 3 = 0', '3x² + 5x + 2 = 0', '−3x² + 5x + 2 = 0'], 'Kökleri 1/x₁ ve 1/x₂ olan denklem, katsayıların sırası ters çevrilerek elde edilir: cx² + bx + a = 0. Asıl kökler 1 ve 3/2, yenileri 1 ve 2/3\'tür.'),
  ('x² − 3x + 1 = 0 denkleminin her kökü 1 artırılarak yeni kökler oluşturuluyor. Bu yeni köklere sahip, başkatsayısı 1 olan denklem hangisidir?', 'x² − 5x + 5 = 0', ['x² − 5x + 3 = 0', 'x² − x − 1 = 0', 'x² − 3x + 2 = 0'], 'Yeni kök y = x + 1 ise x = y − 1 yazılır: (y − 1)² − 3(y − 1) + 1 = y² − 5y + 5.'),
  ('x² − 3x + 1 = 0 denkleminin köklerinin kareleri, başkatsayısı 1 olan hangi denklemi sağlar?', 'x² − 7x + 1 = 0', ['x² − 9x + 1 = 0', 'x² + 7x + 1 = 0', 'x² − 5x + 1 = 0'], 'Yeni kökler toplamı x₁² + x₂² = 9 − 2 = 7, çarpımı (x₁x₂)² = 1\'dir. Denklem x² − 7x + 1 = 0 olur.'),
  ('x² − 5x + 6 = 0 denkleminin kökler toplamı ve kökler çarpımı, yeni bir denklemin kökleri olarak alınıyor. Başkatsayısı 1 olan bu yeni denklem hangisidir?', 'x² − 11x + 30 = 0', ['x² − 30x + 11 = 0', 'x² + 11x + 30 = 0', 'x² − 5x + 6 = 0'], 'Yeni kökler 5 ve 6\'dır. Toplamları 11, çarpımları 30 olduğundan denklem x² − 11x + 30 = 0\'dır.'),
  ('x² − 9x + m = 0 denkleminin kökleri ardışık iki tam sayı olduğuna göre m kaçtır?', '20', ['18', '14', '81/4'], 'Ardışık iki tam sayının toplamı 9 ise bunlar 4 ve 5\'tir; m = 4·5 = 20 olur.'),
  ('x² + (m² − 9)x − 5 = 0 denkleminin kökleri birbirinin toplama işlemine göre tersidir. m pozitif olduğuna göre değeri kaçtır?', '3', ['−3', '9', '5'], 'Kökler toplamı sıfır olmalıdır: −(m² − 9) = 0, m² = 9. Pozitif değer m = 3\'tür; çarpım −5 olduğundan kökler gerçektir.'),
  ('(k + 1)x² − 9x + 3k − 3 = 0 denkleminin kökleri birbirinin çarpmaya göre tersi olduğuna göre k kaçtır?', '2', ['1', '3', '−2'], 'Kökler çarpımı 1 olmalıdır: (3k − 3)/(k + 1) = 1, buradan k = 2. Denklem 3x² − 9x + 3 = 0 olur ve Δ = 45 > 0\'dır.'),
  ('x² − 7x + m = 0 denkleminin kökleri x₁ ve x₂ arasında 2x₁ + x₂ = 11 bağıntısı vardır. m kaçtır?', '12', ['10', '6', '28'], 'x₁ + x₂ = 7 olduğundan 2x₁ + x₂ = x₁ + 7 = 11, x₁ = 4 ve x₂ = 3 bulunur. m = 12\'dir.'),
  ('Bir P(x) = 0 denkleminin kökleri x₁ ve x₂\'dir. Buna göre P(x − 4) = 0 denkleminin kökleri hangileridir?', 'x₁ + 4 ve x₂ + 4', ['x₁ − 4 ve x₂ − 4', '4x₁ ve 4x₂', 'x₁/4 ve x₂/4'], 'P(x − 4) = 0 olması için x − 4 = x₁ veya x − 4 = x₂ olmalıdır; kökler 4 birim artar.'),
  ('İki ikinci dereceden denklemin ortak kökü aranırken en pratik ilk adım genellikle hangisidir?', 'Denklemleri taraf tarafa çıkarmak', ['Denklemleri taraf tarafa çarpmak', 'Diskriminantlarını birbirine eşitlemek', 'Kökler toplamlarını eşitlemek'], 'Ortak kök iki denklemi de sağladığı için farklarını da sağlar; çıkarma x² terimini yok edip birinci dereceden bir denklem verir.'),
  ('x² + ax + 6 = 0 ile 2x² − 10x + b = 0 denklemlerinin çözüm kümeleri aynıdır. a + b toplamı kaçtır?', '7', ['17', '−7', '1'], 'İkinci denklem 2\'ye bölünürse x² − 5x + b/2 = 0 olur. Katsayılar eşleşmeli: a = −5, b = 12; toplam 7\'dir.'),
  ('x² + (m − 2)x + m² − 9 = 0 denkleminin köklerinden biri sıfır, diğeri pozitiftir. m kaçtır?', '−3', ['3', '2', '±3'], 'Sıfır kök için sabit terim m² − 9 = 0, m = ±3 olmalıdır. Diğer kök 2 − m\'dir; pozitif olması için m = −3 seçilir (diğer kök 5).'),
  ('2x² + (a − 1)x + a = 0 denkleminin köklerinden biri 1 olduğuna göre öteki kök kaçtır?', '−1/4', ['1/4', '−1/2', '4'], 'x = 1 yazılınca 2 + a − 1 + a = 0, a = −1/2 olur. Kökler çarpımı a/2 = −1/4 olduğundan diğer kök −1/4\'tür.'),
  ('ax² + bx + c = 0 denkleminin birbirinden farklı iki pozitif gerçek kökü olması için hangi koşulların birlikte sağlanması gerekir?', 'Δ > 0, kökler çarpımı > 0 ve kökler toplamı > 0', ['Δ > 0, kökler çarpımı < 0 ve kökler toplamı > 0', 'Yalnızca Δ > 0 olması ve kökler toplamının pozitif olması', 'Δ > 0, kökler çarpımı > 0 ve kökler toplamı < 0'], 'Gerçek ve farklı kökler için Δ > 0 gerekir. Aynı işaretli olmaları için çarpım pozitif, ikisinin de pozitif olması için toplam pozitif olmalıdır.'),
  ('x² + bx + c = 0 denkleminin kökleri ardışık iki tam sayıdır. Bu denklemin diskriminantı kaçtır?', '1', ['0', '4', 'b²'], 'Başkatsayı 1 iken Δ = (x₁ − x₂)²\'dir. Ardışık tam sayıların farkı 1 olduğundan Δ = 1 bulunur.'),
  ('x² + (m − 3)x − 4 = 0 denkleminin kökleri ters işaretlidir. Negatif kökün mutlak değerinin pozitif kökten büyük olması için m hangi koşulu sağlamalıdır?', 'm > 3', ['m < 3', 'm > −3', 'm < −3'], 'Çarpım −4 olduğundan kökler her zaman ters işaretlidir. Negatif kökün mutlak değeri büyükse toplam negatiftir: −(m − 3) < 0, yani m > 3.'),
  ('a > 0, b > 0 ve c < 0 olmak üzere ax² + bx + c = 0 denkleminin kökleri için hangisi doğrudur?', 'Ters işaretlidir; negatif kökün mutlak değeri daha büyüktür', ['Ters işaretlidir; pozitif kökün mutlak değeri daha büyüktür', 'İki kök de negatiftir', 'İki kök de pozitif ve birbirine eşittir'], 'c/a < 0 olduğundan kökler ters işaretlidir. Toplam −b/a < 0 olduğundan negatif kök mutlak değerce daha büyüktür.'),
  ('x² − 4x + m = 0 denkleminin kökleri x₁ < 1 < x₂ sıralamasını sağladığına göre m hangi koşulu sağlar?', 'm < 3', ['m > 3', 'm < 4', '3 < m < 4'], 'Başkatsayı pozitif olduğundan 1 sayısının kökler arasında olması için f(1) < 0 gerekir: 1 − 4 + m < 0, m < 3. Bu koşul Δ > 0\'ı da sağlar.'),
  ('f(x) = ax² + bx + c ve a > 0 olmak üzere bir k sayısı için f(k) < 0 bulunmuştur. k\'nın f(x) = 0 denkleminin kökleri karşısındaki konumu nedir?', 'İki kökün arasındadır', ['İki kökten de küçüktür', 'İki kökten de büyüktür', 'Köklerden birine eşittir'], 'a > 0 iken ifade yalnız kökler arasında negatif değer alır. f(k) < 0 ise denklemin iki farklı gerçek kökü vardır ve k bunların arasındadır.'),
  ('Katsayıları rasyonel olan x² + bx + c = 0 denkleminin bir kökü 2 + √3\'tür. b + c toplamı kaçtır?', '−3', ['5', '−5', '−5/4'], 'Diğer kök eşlenik olan 2 − √3\'tür. Toplam 4 olduğundan b = −4, çarpım 1 olduğundan c = 1; b + c = −3 olur.'),
  ('2x² − 3x − 7 = 0 denkleminin iki gerçek kökü arasında (uçlar hariç) kaç tam sayı bulunur?', '4', ['3', '5', '2'], 'f(−1) = −2 < 0 ve f(2) = −5 < 0, buna karşılık f(−2) = 7 > 0 ve f(3) = 2 > 0\'dır. Kökler arasındaki tam sayılar −1, 0, 1, 2\'dir.'),
  ('k bir gerçek sayı olmak üzere x² − (k + 4)x + 4k = 0 denkleminin k\'ya bağlı olmayan, hep aynı kalan kökü hangisidir?', '4', ['−4', '2', '1'], 'Denklem gruplanarak (x − 4)(x − k) = 0 biçiminde yazılır. Kökler 4 ve k\'dır; k ne olursa olsun 4 bir köktür.'),
  ('Aşağıdaki denklemlerden hangisinin kökleri rasyonel sayılardır?', '2x² − x − 3 = 0', ['x² − x − 3 = 0', 'x² + 2x − 1 = 0', '3x² − x − 1 = 0'], 'Rasyonel katsayılı denklemde kökler Δ tam kare olduğunda rasyoneldir. 2x² − x − 3 = 0 için Δ = 25\'tir; diğerlerinde Δ = 13, 8 ve 13\'tür.'),
  ('Rasyonel katsayılı ve başkatsayısı 1 olan bir ikinci derece denklemin bir kökü 1/(2 − √3) sayısıdır. Bu denklem hangisidir?', 'x² − 4x + 1 = 0', ['x² + 4x + 1 = 0', 'x² − 4x − 1 = 0', 'x² − 2x − 3 = 0'], 'Payda rasyonelleştirilince kök 2 + √3 olur. Eşleniği 2 − √3 ile toplam 4, çarpım 1 bulunur.'),
  ('4ˣ − 6·2ˣ + 8 = 0 üstel denklemi 2ˣ = t dönüşümüyle ikinci dereceye indirgenerek çözülüyor. Bulunan x değerlerinin toplamı kaçtır?', '3', ['6', '2', '12'], '4ˣ = t² olduğundan t² − 6t + 8 = 0 elde edilir; t = 2 veya t = 4. Buradan x = 1 ve x = 2 bulunur, toplam 3\'tür.'),
  ('x − 5√x + 6 = 0 denkleminde √x = t alınarak çözüm yapılıyor. Denklemi sağlayan x değerlerinin toplamı kaçtır?', '13', ['5', '6', '36'], 't² − 5t + 6 = 0\'dan t = 2 veya t = 3 bulunur. x = t² olduğundan x = 4 ve x = 9\'dur; toplam 13\'tür.'),
  ('Köklü denklemlerde her iki tarafın karesini almak neden yabancı kök ortaya çıkarabilir?', 'a² = b² eşitliği a = −b iken de sağlandığı için', ['Kare alma işlemi çözüm kümesini her zaman daralttığı için', 'Karekök yalnız negatif sayılarda tanımlı olduğu için', 'Kare alma denklemin derecesini düşürdüğü için'], 'Kare alma tersinir bir işlem değildir: a = b ile birlikte a = −b durumundaki çözümleri de getirir. Bu yüzden bulunan kökler asıl denklemde denenmelidir.'),
  ('1/(x − 1) + 2/(x + 1) = 1 kesirli denkleminin çözüm kümesi aşağıdakilerden hangisidir?', '{0, 3}', ['{3}', '{1, 3}', '{−1, 3}'], 'Ortak payda (x − 1)(x + 1) ile çarpılınca 3x − 1 = x² − 1, yani x² − 3x = 0 olur. Kökler 0 ve 3 paydaları sıfırlamaz.'),
  ('(x + 2)/(x − 1) = 3/(x² − x) denklemi paydalardan kurtarılınca x² + 2x − 3 = 0 elde ediliyor. Asıl denklemin çözüm kümesi nedir?', '{−3}', ['{1}', '{1, −3}', '{3}'], 'x² + 2x − 3 = 0\'ın kökleri 1 ve −3\'tür. x = 1 paydayı sıfır yaptığından atılır; çözüm kümesi {−3}\'tür.'),
  ('|x² − 4| = 3 denklemini sağlayan kaç farklı gerçek sayı vardır?', '4', ['2', '3', '1'], 'x² − 4 = 3 için x = ±√7, x² − 4 = −3 için x = ±1 bulunur. Toplam dört farklı kök vardır.'),
  ('x² − 2|x| − 3 = 0 denkleminde |x| = t yazılarak çözüm yapılıyor. Denklemin gerçek sayılardaki çözüm kümesi hangisidir?', '{−3, 3}', ['{−1, 3}', '{−3, −1, 1, 3}', '{3}'], 't² − 2t − 3 = 0\'dan t = 3 veya t = −1 çıkar. |x| negatif olamayacağından yalnız |x| = 3 kalır: x = ±3.'),
  ('|x² − 5x| = 6 eşitliğini sağlayan bütün gerçek sayıların toplamı kaçtır?', '10', ['5', '4', '12'], 'x² − 5x = 6 için kökler 6 ve −1, x² − 5x = −6 için kökler 2 ve 3\'tür. Dört kökün toplamı 10\'dur.'),
  ('x⁴ + 3x² − 4 = 0 denkleminin gerçek sayılarda kaç kökü vardır?', '2', ['4', '0', '1'], 'x² = t ile t² + 3t − 4 = 0, t = 1 veya t = −4 olur. x² = −4\'ün gerçek çözümü yoktur; x² = 1\'den x = ±1 olmak üzere iki kök kalır.'),
  ('2/x² − 3/x + 1 = 0 denklemi 1/x = t dönüşümüyle çözülürse hangi x değerleri elde edilir?', '1 ve 2', ['1 ve 1/2', '−1 ve −2', '2 ve 3'], '2t² − 3t + 1 = 0\'dan t = 1 veya t = 1/2 bulunur. x = 1/t olduğundan x = 1 ve x = 2\'dir.'),
  ('√(x² − 3x) = 2 eşitliğinin gerçek sayılardaki bütün çözümleri hangileridir?', '−1 ve 4', ['Yalnız 4', '1 ve −4', 'Yalnız −1'], 'Kare alınca x² − 3x − 4 = 0 olur. x = 4 ve x = −1 için kök içi 4\'tür ve sağ taraf pozitiftir; ikisi de geçerlidir.'),
  ('y = x + 1 ve x² + y² = 13 denklem sisteminin bütün çözümleri hangi seçenekte verilmiştir?', '(2, 3) ve (−3, −2)', ['(3, 2) ve (−2, −3)', '(2, 3) ve (3, 2)', '(−2, −1), (3, 4) ve (2, 3)'], 'y yerine x + 1 yazılınca 2x² + 2x − 12 = 0, yani x² + x − 6 = 0 olur. x = 2 için y = 3, x = −3 için y = −2 bulunur.'),
  ('Toplamları 10, kareleri toplamı 58 olan iki sayı arasındaki pozitif fark kaçtır?', '4', ['10', '21', '2√21'], 'xy = (100 − 58)/2 = 21 olur. (x − y)² = 100 − 84 = 16 olduğundan fark 4\'tür (sayılar 3 ve 7).'),
  ('2x + y = 5 ve xy = 2 sisteminin çözümlerinde ortaya çıkan x değerlerinin toplamı kaçtır?', '5/2', ['5', '2', '17/4'], 'y = 5 − 2x yazılınca x(5 − 2x) = 2, yani 2x² − 5x + 2 = 0 olur. x değerleri 2 ve 1/2\'dir; toplamları 5/2\'dir.'),
  ('Farkı 3 ve çarpımı 54 olan iki pozitif sayının toplamı kaçtır?', '15', ['12', '18', '6√6'], 'Küçük sayı x ise x(x + 3) = 54, x² + 3x − 54 = 0 ve x = 6 bulunur. Sayılar 6 ve 9, toplam 15\'tir.'),
  ('Ardışık iki pozitif tek sayının karelerinin toplamı 130\'dur. Bu sayılardan büyük olanı kaçtır?', '9', ['7', '11', '13'], 'Sayılar x ve x + 2 ise x² + (x + 2)² = 130, x² + 2x − 63 = 0 ve x = 7 bulunur. Büyük sayı 9\'dur.'),
  ('İki basamaklı bir sayının rakamlarının çarpımı 24\'tür. Rakamların yeri değiştirilince sayı 18 artmaktadır. Bu sayı kaçtır?', '46', ['64', '38', '83'], 'Sayı 10a + b ise yer değiştirme 9(b − a) = 18, b = a + 2 verir. a(a + 2) = 24\'ten a = 4, b = 6 bulunur.'),
  ('20 cm × 30 cm boyutlarındaki bir fotoğrafın çevresine her yerde aynı genişlikte bir çerçeve takılıyor. Çerçeveyle birlikte toplam alan 1200 cm² olduğuna göre çerçevenin genişliği kaç cm\'dir?', '5', ['10', '6', '3'], '(20 + 2x)(30 + 2x) = 1200 denklemi x² + 25x − 150 = 0 biçimine gelir. Pozitif kök x = 5\'tir.'),
  ('Dik kenarlarından biri diğerinden 7 cm uzun olan bir dik üçgenin hipotenüsü 13 cm\'dir. Üçgenin alanı kaç cm²\'dir?', '30', ['60', '65', '32,5'], 'x² + (x + 7)² = 169\'dan x² + 7x − 60 = 0 ve x = 5 bulunur. Dik kenarlar 5 ve 12, alan 5·12/2 = 30\'dur.'),
  ('30 cm × 20 cm\'lik bir kartonun dört köşesinden x cm kenarlı eş kareler kesilip kenarlar katlanarak üstü açık bir kutu yapılıyor. Kutunun taban alanı 336 cm² ise x kaçtır?', '3', ['22', '6', '3 veya 22'], '(30 − 2x)(20 − 2x) = 336 denklemi x² − 25x + 66 = 0 olur; kökler 3 ve 22\'dir. x = 22 için kenarlar negatif olacağından yalnız x = 3 geçerlidir.'),
  ('Ardışık üç doğal sayıdan en küçüğünün karesi, diğer ikisinin toplamına eşittir. Bu üç sayının toplamı kaçtır?', '12', ['9', '15', '6'], 'Sayılar n, n + 1, n + 2 ise n² = 2n + 3, n² − 2n − 3 = 0 ve n = 3 bulunur. Sayılar 3, 4, 5; toplam 12\'dir.'),
  ('Bir bisikletli 60 km\'lik yolu, hızını saatte 5 km artırsaydı 1 saat daha erken tamamlayacaktı. Bisikletlinin gerçek hızı saatte kaç km\'dir?', '15', ['20', '12', '7,5'], '60/v − 60/(v + 5) = 1 eşitliğinden v² + 5v − 300 = 0 elde edilir. (v − 15)(v + 20) = 0\'dan v = 15 km/sa bulunur.'),
  ('Bir kavşaktan aynı anda iki araç yola çıkıyor: biri kuzeye, diğeri doğuya gidiyor. Doğuya giden saatte 2 km daha hızlıdır ve 1 saat sonra araçlar arasındaki kuş uçuşu uzaklık 10 km oluyor. Hızlı aracın hızı saatte kaç km\'dir?', '8', ['6', '10', '7'], 'Yollar dik olduğundan v² + (v + 2)² = 100, yani v² + 2v − 48 = 0 olur. v = 6 bulunur; hızlı araç 8 km/sa ile gider.'),
  ('Yukarı atılan bir topun yüksekliği h(t) = −5t² + 25t metredir. Top kaç saniye boyunca 30 m\'nin üzerinde kalır?', '1', ['2', '3', '1,5'], '−5t² + 25t > 30 eşitsizliği t² − 5t + 6 < 0, yani 2 < t < 3 verir. Bu aralığın uzunluğu 1 saniyedir.'),
  ('Yüksekliği h(t) = −5t² + 30t metre olan bir cisim, yükselirken ve düşerken 40 m seviyesinden iki kez geçer. Bu iki geçiş arasında kaç saniye vardır?', '2', ['4', '6', '2,5'], '−5t² + 30t = 40\'tan t² − 6t + 8 = 0 ve t = 2, t = 4 bulunur. Aradaki süre 2 saniyedir.'),
  ('Bir aracın fren mesafesi, v km/sa hızla giderken yaklaşık d = v²/20 + v metre olarak modelleniyor. Fren mesafesi 75 m olduğuna göre araç saatte kaç km hızla gidiyordur?', '30', ['25', '50', '15'], 'v²/20 + v = 75 eşitliği 20 ile çarpılınca v² + 20v − 1500 = 0 olur. (v − 30)(v + 50) = 0\'dan v = 30 bulunur.'),
  ('Bir grup arkadaş 360 TL\'lik hesabı eşit paylaşacaktı. İki kişi ödemeye katılmayınca diğerlerinin her biri 6 TL fazla ödedi. Grupta başlangıçta kaç kişi vardı?', '12', ['10', '14', '12,5'], '360/(n − 2) − 360/n = 6 eşitliği n² − 2n − 120 = 0 verir. (n − 12)(n + 10) = 0\'dan n = 12\'dir.'),
  ('Bir ürünün günlük geliri, satış fiyatı p TL iken R = p(100 − 2p) TL\'dir. Geliri 1200 TL yapan iki farklı fiyatın toplamı kaçtır?', '50', ['30', '20', '600'], '100p − 2p² = 1200 eşitliği p² − 50p + 600 = 0 olur. Kökler toplamı 50\'dir (fiyatlar 20 ve 30 TL).'),
  ('Bankaya yatırılan 10.000 TL, iki yıl boyunca her yıl aynı r oranında bileşik faizle büyüyerek 12.100 TL oluyor. Yıllık faiz oranı yüzde kaçtır?', '%10', ['%21', '%11', '%10,5'], '10.000(1 + r)² = 12.100 ise (1 + r)² = 1,21 ve 1 + r = 1,1\'dir. Oran %10 bulunur.'),
  ('Bir duvarın önüne, duvar tarafı açık kalacak biçimde üç kenarı 28 m tel ile çevrilen dikdörtgen bir bölme yapılıyor. Bölmenin alanı 96 m² ise duvara dik kenarın uzunluğu için hangisi doğrudur?', '6 m ya da 8 m olabilir', ['Yalnız 8 m olabilir', 'Yalnız 6 m olabilir', '4 m ya da 12 m olabilir'], 'Dik kenar x ise duvara paralel kenar 28 − 2x olur. x(28 − 2x) = 96\'dan x² − 14x + 48 = 0, x = 6 veya x = 8 bulunur; ikisi de uygundur.'),
  ('Durgun hâlden harekete başlayan bir aracın t saniyede aldığı yol x = 2t² + 3t metredir. Araç 27 m yolu kaç saniyede alır?', '3', ['9/2', '4', '27/5'], '2t² + 3t − 27 = 0 denkleminin kökleri 3 ve −9/2\'dir. Süre pozitif olduğundan t = 3 s\'dir.'),
  ('İki direnç seri bağlanınca eşdeğer direnç 9 Ω, paralel bağlanınca 2 Ω oluyor. Büyük direnç kaç Ω\'dur?', '6', ['4,5', '9', '18'], 'R₁ + R₂ = 9 ve R₁R₂/(R₁ + R₂) = 2 olduğundan R₁R₂ = 18\'dir. Dirençler t² − 9t + 18 = 0\'ın kökleri olan 3 ve 6 Ω\'dur.'),
  ('Harezmî\'nin cebir kitabındaki yöntemde "el-cebr" adı verilen işlem neyi ifade eder?', 'Çıkarılmış bir terimi iki tarafa ekleyip eksiği tamamlamayı', ['İki taraftaki benzer terimleri birbirine karşı sadeleştirmeyi', 'Denklemin iki tarafının karekökünü almayı', 'Bilinmeyeni bir harf simgesiyle göstermeyi'], 'El-cebr "tamamlama, yerine koyma" anlamına gelir: eksi bir terim her iki tarafa eklenerek giderilir. Benzer terimlerin karşılıklı sadeleştirilmesine ise el-mukābele denir.'),
  ('Harezmî\'nin ikinci derece denklemleri tek bir genel biçim yerine birkaç ayrı türde incelemesinin temel nedeni nedir?', 'Negatif sayı ve katsayı kullanmaması', ['Sıfır kavramını bilmesine rağmen yasaklaması', 'Ondalık kesirleri tercih etmesi', 'Denklemleri yalnız sayısal deneme ile çözmesi'], 'Harezmî her terimi pozitif nicelik olarak ele aldığından, terimlerin hangi tarafta bulunduğuna göre farklı türler ortaya çıkmıştır. Negatif katsayılar kabul edilince bu türler tek biçimde birleşir.'),
  ('Harezmî\'nin ünlü örneği olan "bir kare ve on kökü otuz dokuz birime eşittir" ifadesi bugün x² + 10x = 39 olarak yazılır. Bu denklemin pozitif çözümü kaçtır?', '3', ['13', '8', '5'], 'Tam kareye tamamlama ile (x + 5)² = 39 + 25 = 64 olur. x + 5 = 8\'den x = 3 bulunur; Harezmî de bu değeri vermiştir.'),
  ('628 yılında yazdığı Brāhmasphuṭasiddhānta adlı eserde ikinci derece denklemin çözümü için açık bir kural veren ve negatif sayılarla işlem kurallarını tanımlayan Hint matematikçi kimdir?', 'Brahmagupta', ['Aryabhata', 'Bhāskara II', 'Ramanujan'], 'Brahmagupta bu eserinde sıfır ve negatif sayılarla işlem kurallarını vermiş, ax² + bx = c türü denklemler için sözel bir çözüm kuralı yazmıştır.'),
  ('Öklid\'in Elemanlar adlı eserinin II. kitabında bugün ikinci derece denklemlerle ifade edilen problemler hangi yaklaşımla ele alınmıştır?', 'Alan ve uzunluklara dayalı geometrik yollarla', ['Harflerle yazılmış sembolik formüllerle', 'Negatif kökleri de kapsayan sayısal tablolarla', 'Ardışık yaklaşım veren yinelemeli hesaplarla'], 'Antik Yunan matematiğinde cebirsel ilişkiler dikdörtgen ve kare alanları üzerinden kanıtlanırdı; bu yaklaşıma geometrik cebir denir.'),
  ('φ altın oran olmak üzere 1/φ ifadesi aşağıdakilerden hangisine eşittir?', 'φ − 1', ['φ + 1', '2 − φ', 'φ²'], 'φ, x² = x + 1 denklemini sağlar. İki taraf φ\'ye bölünürse φ = 1 + 1/φ, yani 1/φ = φ − 1 elde edilir.'),
  ('Bir dikdörtgenden kısa kenarı üzerine kurulan kare kesilip atıldığında kalan dikdörtgen asıl dikdörtgene benzer kalıyor. Uzun kenarın kısa kenara oranı kaçtır?', '(1 + √5)/2', ['(1 + √3)/2', '√5 − 1', '(3 + √5)/2'], 'Kısa kenar 1, uzun kenar r ise kalan dikdörtgenin kenarları 1 ve r − 1\'dir. r/1 = 1/(r − 1) benzerliği r² − r − 1 = 0 verir; pozitif kök (1 + √5)/2\'dir.'),
  ('x² − x − 1 = 0 denkleminin bir kökü φ olduğuna göre öteki kök φ türünden nasıl yazılır?', '1 − φ', ['−φ', '1/φ', 'φ − 1'], 'Kökler toplamı 1 olduğundan diğer kök 1 − φ\'dir. Bu sayı yaklaşık −0,618\'e eşittir.'),
  ('φ² = φ + 1 bağıntısı kullanılarak φ³ ifadesi aφ + b biçiminde yazılıyor (a ve b tam sayı). a + b toplamı kaçtır?', '3', ['2', '5', '4'], 'φ³ = φ·φ² = φ(φ + 1) = φ² + φ = (φ + 1) + φ = 2φ + 1 olur. a = 2, b = 1 ve toplam 3\'tür.'),
  ('Kökleri 1 ve 4 olan ikinci dereceden denklemlerle ilgili hangisi doğrudur?', 'Sonsuz çoklukta; a(x² − 5x + 4) = 0, a ≠ 0', ['Yalnız bir tane vardır, o da x² − 5x + 4 = 0', 'Böyle bir denklem kurulamaz', 'Tam olarak iki tane vardır'], 'Kökler denklemi başkatsayı dışında belirler. Sıfırdan farklı her a için a(x − 1)(x − 4) = 0 aynı köklere sahiptir.'),
  ('2x² + x − 3 > 0 eşitsizliğinin çözümü aşağıdakilerden hangisidir?', 'x < −3/2 veya x > 1', ['−3/2 < x < 1', 'x < −1 veya x > 3/2', 'x < −3/2 veya x > 3/2'], '2x² + x − 3 = (2x + 3)(x − 1) olup kökler −3/2 ve 1\'dir. a > 0 olduğundan ifade kökler dışında pozitiftir.'),
  ('x² ≤ 4x eşitsizliğini sağlayan bütün gerçek sayılar hangi aralığı oluşturur?', '[0, 4]', ['(−∞, 4]', '[4, ∞)', '(0, 4)'], 'x² − 4x ≤ 0, yani x(x − 4) ≤ 0\'dır; çözüm 0 ≤ x ≤ 4 olur. İki tarafı x\'e bölmek, x\'in işareti bilinmediği için yanlış sonuç verir.'),
  ('(x − 1)² > 0 koşulunu sağlayan x değerleri hangi kümeyi oluşturur?', 'ℝ − {1}', ['ℝ', '∅', 'ℝ − {−1, 1}'], 'Bir kare her zaman sıfır ya da pozitiftir; yalnız x = 1\'de sıfır olur. Kesin eşitsizlik istendiği için 1 dışarıda kalır.'),
  ('−x² + 2x − 3 ≥ 0 eşitsizliğini sağlayan gerçek sayılar için ne söylenebilir?', 'Böyle bir gerçek sayı yoktur', ['Her gerçek sayı sağlar', 'Yalnız x = 1 sağlar', 'Yalnız pozitif sayılar sağlar'], 'Δ = 4 − 12 < 0 ve a = −1 < 0 olduğundan ifade her x için negatiftir. Sıfır ya da pozitif olamaz; çözüm kümesi boştur.'),
  ('x² − 3x − 28 < 0 eşitsizliğini sağlayan kaç tam sayı vardır?', '10', ['11', '12', '9'], 'x² − 3x − 28 = (x − 7)(x + 4) olduğundan çözüm −4 < x < 7\'dir. Bu aralıktaki tam sayılar −3\'ten 6\'ya kadar 10 tanedir.'),
  ('x² − 10x + 21 ≤ 0 eşitsizliğini sağlayan asal sayıların toplamı kaçtır?', '15', ['12', '10', '25'], 'Çözüm 3 ≤ x ≤ 7\'dir. Bu aralıktaki asal sayılar 3, 5 ve 7 olup toplamları 15\'tir.'),
  ('x² − 6x − 16 > 0 eşitsizliğini sağlamayan kaç doğal sayı vardır?', '9', ['8', '10', '11'], 'Kökler 8 ve −2\'dir; ifade −2 ≤ x ≤ 8 aralığında pozitif değildir. Bu aralıktaki doğal sayılar 0, 1, …, 8 olmak üzere 9 tanedir.'),
  ('−2x² + 5x + 3 > 0 eşitsizliğinin çözüm aralığı aşağıdakilerden hangisidir?', '(−1/2, 3)', ['(−∞, −1/2) ∪', '(−3, 1/2)', '(1/2, 3)'], 'Kökler 3 ve −1/2\'dir. Başkatsayı negatif olduğundan ifade kökler arasında pozitiftir.'),
  ('Bir öğrenci x² − 2x − 8 < 0 eşitsizliğinde kökleri 4 ve −2 olarak doğru buluyor, ardından çözümü "x < −2 veya x > 4" diye yazıyor. Öğrencinin hatası nedir?', 'Kökler arasını almalıydı: −2 < x < 4', ['Kökleri yanlış hesaplamıştır', 'Eşitsizliğin yönünü değiştirmeliydi: x > 4', 'Kökleri çözüme dahil etmeliydi'], 'Başkatsayı pozitif olduğundan ifade kökler arasında negatiftir. Öğrencinin yazdığı bölge ifadenin pozitif olduğu yerdir.'),
  ('(2 − x)(x + 5) ≥ 0 eşitsizliğinin çözüm kümesi hangisidir?', '[−5, 2]', ['(−∞, −5] ∪ [2, ∞)', '[−2, 5]', '(−5, 2)'], 'Açılımda x²\'nin katsayısı −1\'dir; kökler −5 ve 2\'dir. a < 0 olduğundan ifade kökler arasında pozitiftir, uçlarda sıfırdır.'),
  ('x(x − 3) ≤ 10 koşuluna uyan bütün tam sayılar toplanırsa sonuç kaç olur?', '12', ['8', '15', '10'], 'x² − 3x − 10 ≤ 0, (x − 5)(x + 2) ≤ 0 verir; çözüm [−2, 5]\'tir. −2\'den 5\'e kadar tam sayıların toplamı 12\'dir.'),
  ('x² − 5x + 6 ≤ 0 eşitsizliğinin çözüm kümesinden x² − 5x + 6 < 0 eşitsizliğinin çözüm kümesi çıkarılırsa hangi küme kalır?', '{2, 3}', ['(2, 3)', '∅', '(2, 3) ∪ {2}'], 'İlki [2, 3], ikincisi (2, 3) aralığıdır. Fark yalnız ifadeyi sıfır yapan uç noktalardır: {2, 3}.'),
  ('a pozitif bir sayı olmak üzere x² − 2x + 1 − a² < 0 eşitsizliğinin çözüm kümesi hangisidir?', '1 − a < x < 1 + a', ['−a < x < a', 'x < 1 − a veya x > 1 + a', 'a − 1 < x < a + 1'], 'İfade (x − 1)² − a² biçimindedir; (x − 1)² < a² ise |x − 1| < a olur ve 1 − a < x < 1 + a bulunur.'),
  ('Karesi 30\'u aşmayan kaç tam sayı vardır?', '11', ['5', '10', '61'], '|x| ≤ √30 ≈ 5,48 olmalıdır. −5\'ten 5\'e kadar 11 tam sayı bu koşulu sağlar.'),
  ('Her gerçek x için ax² + bx + c > 0 olduğu biliniyor. Aşağıdakilerden hangisi kesinlikle doğrudur?', 'a − b + c > 0', ['b > 0', 'a + c < 0', 'b² > 4ac'], 'İfade her x için pozitifse x = −1 için de pozitiftir: a − b + c > 0. Ayrıca Δ < 0 olduğundan b² < 4ac\'dir; b\'nin işareti ise belirsizdir.'),
  ('(m − 2)x² + 4x + 1 > 0 eşitsizliğinin bütün gerçek sayılar için sağlanması isteniyor. m hangi koşulu sağlamalıdır?', 'm > 6', ['m > 2', '2 < m < 6', 'm ≥ 6'], 'Baş katsayı pozitif (m > 2) ve Δ = 16 − 4(m − 2) < 0 (m > 6) olmalıdır. m = 2 iken 4x + 1 > 0 her x için doğru değildir; m = 6\'da ise Δ = 0 olur ve bir noktada ifade sıfırlanır.'),
  ('−x² + 6x + m < 0 eşitsizliği her gerçek x için doğru olduğuna göre m hangi aralıktadır?', 'm < −9', ['m > −9', 'm < 9', 'm < −36'], 'Baş katsayı −1 < 0 olduğundan ifadenin hep negatif olması için Δ = 36 + 4m < 0, yani m < −9 olmalıdır.'),
  ('x² − mx + m − 1 < 0 eşitsizliğinin çözüm kümesi (1, 4) aralığıdır. m kaçtır?', '5', ['4', '3', '6'], 'x = 1 her m için ifadeyi sıfırlar: 1 − m + m − 1 = 0. Kökler çarpımı m − 1 olduğundan diğer kök m − 1\'dir; m − 1 = 4\'ten m = 5 bulunur.'),
  ('x² + bx + c < 0 eşitsizliğinin çözüm kümesi (−1, 5) aralığıdır. b + c toplamı kaçtır?', '−9', ['9', '−1', '−20'], 'Kökler −1 ve 5 olduğundan ifade (x + 1)(x − 5) = x² − 4x − 5\'tir. b = −4, c = −5 ve b + c = −9 olur.'),
  ('Çözüm kümesi (−∞, −2] ∪ [4, ∞) olan eşitsizlik aşağıdakilerden hangisidir?', 'x² − 2x − 8 ≥ 0', ['x² − 2x − 8 ≤ 0', 'x² + 2x − 8 ≥ 0', 'x² − 2x − 8 > 0'], 'Kökleri −2 ve 4 olan ifade (x + 2)(x − 4) = x² − 2x − 8\'dir. Kökler dışı ve uç noktalar istendiği için ≥ 0 seçilir.'),
  ('x² − x − 12 ≤ 0 ve x² − 4x > 0 eşitsizliklerini birlikte sağlayan gerçek sayılar hangi kümeyi oluşturur?', '[−3, 0)', ['[−3, 4]', '(0, 4]', '[−3, 0) ∪'], 'Birincinin çözümü [−3, 4], ikincinin çözümü x < 0 veya x > 4\'tür. Kesişim −3 ≤ x < 0 olur.'),
  ('Hem x² − 6x + 5 < 0 hem de x² − 9 ≥ 0 koşulunu sağlayan tam sayıların toplamı kaçtır?', '7', ['12', '3', '9'], 'Birinci koşul 1 < x < 5, ikincisi x ≤ −3 veya x ≥ 3 verir. Kesişim [3, 5)\'tir; tam sayılar 3 ve 4, toplamları 7\'dir.'),
  ('3 < x² − 1 < 15 çift eşitsizliğinin gerçek sayılardaki çözüm kümesi hangisidir?', '(−4, −2) ∪', ['(2, 4)', '(−4, 4)', '(−4, −2] ∪ [2, 4)'], 'Her tarafa 1 eklenince 4 < x² < 16 olur; bu 2 < |x| < 4 demektir. Negatif değerler de bu koşulu sağlar.'),
  ('x² − 2x + m > 0 eşitsizliği x = 1 dışındaki bütün gerçek sayılar için sağlanıyor ve x = 1\'de sağlanmıyor. m kaçtır?', '1', ['2', '0', '−1'], 'İfadenin yalnız bir noktada sıfır olup başka yerde pozitif olması için tam kare olması gerekir: x² − 2x + 1 = (x − 1)². Buradan m = 1 bulunur.'),
  ('x² + mx + 4 ≤ 0 eşitsizliğinin çözüm kümesi tek elemanlıdır. m\'nin alabileceği değerlerin çarpımı kaçtır?', '−16', ['16', '0', '−4'], 'Tek elemanlı çözüm için ifade bir tam kare olmalı, yani Δ = m² − 16 = 0\'dır. m = 4 veya m = −4; çarpımları −16\'dır.'),
  ('(x − 2)²(x + 1) > 0 koşulunu karşılayan x değerleri için doğru aralık gösterimi hangisidir?', '(−1, 2) ∪', ['(−1, ∞)', '(−∞, −1)', '(2, ∞)'], '(x − 2)² ifadesi x = 2 dışında pozitiftir; işareti x + 1 belirler. x > −1 olmalı, ancak x = 2\'de ifade sıfır olduğundan bu nokta çıkarılır.'),
  ('(x² − 9)/(x − 1) kesrinin pozitif olmadığı x değerleri hangi kümede toplanır?', '(−∞, −3] ∪ (1, 3]', ['[−3, 1) ∪ [3, ∞)', '(−∞, −3] ∪ [1, 3]', '[−3, 3]'], 'Payın kökleri −3 ve 3, paydanın kökü 1\'dir. İşaret tablosunda ifade x < −3 ve 1 < x < 3 aralıklarında negatiftir; paydanın kökü 1 hiçbir zaman çözüme katılmaz.'),
  ('Paydası her zaman pozitif olan (x² − x − 6)/(x² + x + 1) ≥ 0 eşitsizliğinin çözümü hangi aralıklardan oluşur?', '(−∞, −2] ∪ [3, ∞)', ['[−2, 3]', '(−∞, −2) ∪', '[−3, 2]'], 'Paydanın diskriminantı 1 − 4 < 0 olduğundan payda daima pozitiftir. İşaret yalnız payla belirlenir: (x − 3)(x + 2) ≥ 0.'),
  ('Bir öğrenci (x² − 1)/x > 0 ifadesinde paydadan kurtulmak için iki yanı x ile çarpıyor, x² − 1 > 0 yazıp x < −1 veya x > 1 sonucuna varıyor. Bu çalışma nasıl değerlendirilmelidir?', 'Yanlıştır; doğru çözüm (−1, 0) ∪ (1, ∞) olmalıdır', ['Doğrudur; x ile çarpmak eşitsizliği değiştirmez', 'Yanlıştır; doğru çözüm (−1, 1) olmalıdır', 'Yanlıştır; doğru çözüm (0, 1) olmalıdır'], 'x\'in işareti bilinmeden çarpmak hatalıdır. İşaret tablosunda ifade −1 < x < 0 ve x > 1 için pozitiftir.'),
  ('Dördüncü kuvvet çarpanı içeren (x + 3)⁴(x − 1)(x − 5) < 0 eşitsizliğine kaç tam sayı uyar?', '3', ['4', '5', '2'], '(x + 3)⁴ çift kuvvet olduğundan işareti etkilemez (x = −3\'te ifade sıfırdır). (x − 1)(x − 5) < 0 için 1 < x < 5 olur; tam sayılar 2, 3, 4\'tür.'),
  ('Payı tam kare olan (x² − 4x + 4)/(x − 3) kesrinin negatif değer aldığı x\'ler hangi kümededir?', '(−∞, 2) ∪', ['(−∞, 3)', '(2, 3)', '(3, ∞)'], 'Pay (x − 2)²\'dir ve x = 2\'de sıfırdır, diğer yerlerde pozitiftir. Kesrin negatif olması için x < 3 ve x ≠ 2 gerekir.'),
  ('İkinci çarpanı her zaman pozitif olan (x² − 5x + 6)(x² − 2x + 5) ≤ 0 eşitsizliğinin çözümü nedir?', '[2, 3]', ['(−∞, 2] ∪ [3, ∞)', '[1, 3]', '∅'], 'x² − 2x + 5 ifadesinin Δ\'sı 4 − 20 < 0 olduğundan her x için pozitiftir. Eşitsizlik (x − 2)(x − 3) ≤ 0\'a indirgenir.'),
  ('x⁴ − 2x² + 1 ifadesinin kesin pozitif olduğu x değerleri hangi kümeyi oluşturur?', 'ℝ − {−1, 1}', ['ℝ', '(−1, 1)', 'ℝ − {1}'], 'İfade (x² − 1)² biçiminde bir tam karedir; yalnız x = ±1\'de sıfır olur. Diğer bütün x değerlerinde pozitiftir.'),
  ('Bir tam karenin sıfırdan küçük ya da sıfıra eşit olması istenmektedir: (x² − 2x − 3)² ≤ 0. Bu koşula uyan x değerleri nelerdir?', 'Yalnız −1 ve 3', ['−1 ile 3 arasındaki tüm sayılar', 'Hiçbir gerçek sayı', 'Yalnız 1 ve −3'], 'Bir kare negatif olamaz; ≤ 0 koşulu ancak ifade sıfır olduğunda sağlanır. x² − 2x − 3 = 0\'ın kökleri −1 ve 3\'tür.'),
  ('x⁴ < 4x² eşitsizliğini x²\'ye bölmeden çözünce hangi küme bulunur?', '(−2, 0) ∪ (0, 2)', ['(−2, 2)', '(0, 2)', '(−∞, −2) ∪ (2, ∞)'], 'x²(x² − 4) < 0 yazılır. x² ≥ 0 olduğundan x ≠ 0 ve x² < 4 gerekir; x = 0\'da ifade sıfırdır ve eşitsizlik sağlanmaz.'),
  ('|x² − 5| < 4 mutlak değerli eşitsizliği çözülürken önce −4 < x² − 5 < 4 yazılıyor. Sonuçta bulunan küme hangisidir?', '(−3, −1) ∪', ['(1, 3)', '(−3, 3)', '(−3, −1] ∪ [1, 3)'], '−4 < x² − 5 < 4 ise 1 < x² < 9\'dur. Bu, 1 < |x| < 3 demektir; negatif değerler de dahil olmak üzere iki aralık çıkar.'),
  ('|x² − 2x| ≤ 3 koşulunu sağlayan gerçek sayılar hangi aralıkta toplanır?', '[−1, 3]', ['[−3, 1]', '[0, 2]', '(−∞, −1] ∪ [3, ∞)'], '−3 ≤ x² − 2x ≤ 3 yazılır. Sol taraf x² − 2x + 3 ≥ 0 her x için doğrudur (Δ < 0); sağ taraf x² − 2x − 3 ≤ 0 ise [−1, 3] verir.'),
  ('x² − |x| − 2 > 0 eşitsizliğinde x² = |x|² olduğu kullanılarak çözüm yapılıyor. Çözüm kümesi hangisidir?', '(−∞, −2) ∪', ['(2, ∞)', '(−2, 2)', '(−∞, −1) ∪ (2, ∞) ∪ {0}'], '|x| = t ile t² − t − 2 > 0, (t − 2)(t + 1) > 0 olur. t ≥ 0 olduğundan t > 2, yani |x| > 2 gerekir.'),
  ('|x|² − 5|x| + 4 < 0 eşitsizliğini sağlayan tam sayıların adedi nedir?', '4', ['2', '6', '8'], '|x| = t ile t² − 5t + 4 < 0, 1 < t < 4 bulunur. 1 < |x| < 4 koşulunu ±2 ve ±3 olmak üzere dört tam sayı sağlar.'),
  ('√(12 + x − x²) ifadesini gerçek sayı yapan kaç tam sayı vardır?', '8', ['7', '9', '6'], '12 + x − x² ≥ 0, yani x² − x − 12 ≤ 0 olmalıdır; (x − 4)(x + 3) ≤ 0\'dan −3 ≤ x ≤ 4 bulunur. Bu aralıkta 8 tam sayı vardır.'),
  ('1/√(x² − 1) ifadesinin tanımlı olduğu gerçek sayılar hangi kümeyi oluşturur?', '(−∞, −1) ∪', ['(−∞, −1] ∪ [1, ∞)', '(−1, 1)', '(1, ∞) ∪ (−∞, −1]'], 'Karekök içi negatif olmamalı, payda da sıfır olmamalıdır; bu yüzden x² − 1 > 0 gerekir. ±1 noktaları paydayı sıfırladığı için dışarıda kalır.'),
  ('√(−x² + 4x − 4) ifadesini tanımlı yapan gerçek sayılar nelerdir?', 'Yalnız x = 2', ['2 ≤ x ≤ 4', 'Hiçbir gerçek sayı', 'x ≤ 2 olan her sayı'], 'Kök içi −(x − 2)² olup hiçbir zaman pozitif olmaz; yalnız x = 2\'de sıfırdır. Bu yüzden ifade tek bir noktada tanımlıdır.'),
  ('√(9 − x²) + √(x² − 4) toplamının tanımlı olduğu x değerleri aşağıdakilerden hangisidir?', '[−3, −2] ∪ [2, 3]', ['[2, 3]', '[−3, 3] − {0}', '(−∞, −2] ∪ [2, ∞)'], 'İki koşul birlikte sağlanmalıdır: 9 − x² ≥ 0 için −3 ≤ x ≤ 3, x² − 4 ≥ 0 için |x| ≥ 2. Kesişim 2 ≤ |x| ≤ 3\'tür.'),
  ('Bir aracın her 100 km\'de harcadığı yakıt, v km/sa hızla giderken y = 0,01v² − 1,6v + 70 litre olarak modellenmiştir. Tüketimin 10 litreyi aşmadığı hızlar hangi aralıktadır?', '60 ≤ v ≤ 100', ['0 ≤ v ≤ 60', 'v ≥ 100', '80 ≤ v ≤ 120'], '0,01v² − 1,6v + 60 ≤ 0 eşitsizliği 100 ile çarpılınca v² − 160v + 6000 ≤ 0 olur. Kökler 60 ve 100\'dür; çözüm kökler arasıdır.'),
  ('Bir tiyatro bilet fiyatını p TL yaptığında 300 − 10p bilet satabiliyor. Gelirin en az 2000 TL olması için bilet fiyatı hangi aralıkta seçilmelidir?', '10 ≤ p ≤ 20', ['0 ≤ p ≤ 10', '20 ≤ p ≤ 30', '15 ≤ p ≤ 25 ya da p ≥ 30'], 'p(300 − 10p) ≥ 2000 eşitsizliği p² − 30p + 200 ≤ 0\'a dönüşür. Kökler 10 ve 20 olduğundan çözüm [10, 20]\'dir.'),
  ('Bir ilacın kandaki derişimi t saat sonra C(t) = −0,5t² + 4t mg/L\'dir. İlaç derişim 6 mg/L ve üzerindeyken etkilidir. İlaç toplam kaç saat etkili kalır?', '4', ['2', '6', '8'], '−0,5t² + 4t ≥ 6 eşitsizliği t² − 8t + 12 ≤ 0 olur; çözüm 2 ≤ t ≤ 6\'dır. Etkili süre 6 − 2 = 4 saattir.'),
  ('x² ≤ |x| eşitsizliğini sağlayan gerçek sayıların oluşturduğu küme hangisidir?', '[−1, 1]', ['[0, 1]', '(−∞, −1] ∪ [1, ∞)', '{−1, 0, 1}'], 'x² = |x|² olduğundan |x|(|x| − 1) ≤ 0 yazılır. |x| ≥ 0 iken bu 0 ≤ |x| ≤ 1 demektir.'),
  ('x ve y gerçek sayılar olmak üzere x² + y² − 4x + 6y + 20 ifadesinin alabileceği en küçük değer kaçtır?', '7', ['20', '−13', '4'], 'İfade (x − 2)² + (y + 3)² + 7 biçiminde iki tam kareye ayrılır. Kareler en az 0 olabildiğinden en küçük değer 7\'dir (x = 2, y = −3).'),
  ('x² + y² = 2x + 4y − 5 eşitliğini sağlayan gerçek x ve y sayıları için x + y toplamı kaçtır?', '3', ['−3', '5', '1'], 'Terimler bir tarafa toplanınca (x − 1)² + (y − 2)² = 0 olur. İki karenin toplamı ancak ikisi de sıfırsa sıfırdır: x = 1, y = 2.'),
  ('x + y = 6 koşulunu sağlayan gerçek sayılar için x² + y² toplamının en küçük değeri kaçtır?', '18', ['36', '12', '−18'], 'y = 6 − x yazılınca x² + (6 − x)² = 2x² − 12x + 36 = 2(x − 3)² + 18 olur. En küçük değer 18\'dir.'),
  ('Toplamı 20 olan iki sayıdan birinin karesi ile diğerinin 4 katı toplanıyor. Bu toplam en az kaç olabilir?', '76', ['80', '100', '64'], 'Sayılar x ve 20 − x ise toplam x² − 4x + 80 = (x − 2)² + 76\'dır. En küçük değer x = 2\'de 76\'dır.'),
  ('1/(x² − 4x + 7) kesrinin alabileceği en büyük değer kaçtır?', '1/3', ['1/7', '3', '1/√3'], 'Payda (x − 2)² + 3 ≥ 3\'tür ve hep pozitiftir. Payda en küçükken kesir en büyük olur: 1/3.'),
  ('x⁴ − 6x² + 5 ifadesinin gerçek sayılarda alabileceği en küçük değer kaçtır?', '−4', ['5', '−1', '−√3'], 'x² = t ≥ 0 ile ifade t² − 6t + 5 = (t − 3)² − 4 olur. t = 3, yani x = ±√3 için en küçük değer −4\'tür.'),
  ('(m² − 4)x² + (m − 2)x + 3 = 0 eşitliğinde x² terimi yok olurken geriye gerçekten doğrusal bir denklem kalması isteniyor. m hangi değeri almalıdır?', '−2', ['2', '±2', '−2 ya da 0'], 'x²\'nin katsayısı sıfır olmalı: m = ±2. Ancak m = 2 iken x\'in katsayısı da sıfır olur ve 3 = 0 çelişkisi çıkar. Bu yüzden m = −2\'dir.'),
  ('(k − 3)x² − 4x + 2 = 0 denkleminin gerçek sayılarda hiç çözümü olmaması için k hangi koşulu sağlamalıdır?', 'k > 5', ['k > 3', 'k < 5', '3 < k < 5'], 'k = 3\'te denklem −4x + 2 = 0 olur ve x = 1/2 çözümü vardır. k ≠ 3 için Δ = 16 − 8(k − 3) < 0\'dan k > 5 bulunur.'),
  ('(x² − 1)(x² − m) = 0 denkleminin tam olarak üç farklı gerçek kökü olması için m kaç olmalıdır?', '0', ['1', '−1', '4'], 'x² − 1 = 0 zaten ±1 köklerini verir. Üçüncü ve tek bir yeni kök ancak x² = m\'nin tek çözümü olduğunda eklenir; bu m = 0 (x = 0) durumudur.'),
  ('x² + |x| + m = 0 denkleminin gerçek kökünün bulunmaması için m hangi koşulu sağlamalıdır?', 'm > 0', ['m < 0', 'm > 1/4', 'm ≥ 0'], 'x² + |x| her x için 0 ya da pozitiftir ve 0\'dan başlayarak bütün pozitif değerleri alır. Denklem ancak −m ≥ 0 iken çözülebilir; çözüm olmaması için m > 0 gerekir.'),
  ('y ≠ 0 olmak üzere x² − 3xy + 2y² = 0 eşitliği veriliyor. x/y oranının alabileceği değerlerin toplamı kaçtır?', '3', ['2', '−3', '1'], 'Eşitlik y²\'ye bölünüp t = x/y yazılırsa t² − 3t + 2 = 0 olur. t = 1 veya t = 2\'dir; toplam 3\'tür.'),
  ('İrrasyonel katsayılı x² − 2√2x − 6 = 0 denkleminin kökleri hangileridir?', '3√2 ve −√2', ['−3√2 ve √2', '2√2 ve −√2', '3√2 ve √2'], 'Δ/4 = 2 + 6 = 8 olduğundan x = √2 ± 2√2 bulunur; kökler 3√2 ve −√2\'dir.'),
  ('(x² − 3)² = 1 denkleminin bütün gerçek köklerinin çarpımı kaçtır?', '8', ['−8', '4', '2'], 'x² − 3 = ±1 olduğundan x² = 4 veya x² = 2\'dir. Kökler ±2 ve ±√2; çarpımları (−4)·(−2) = 8\'dir.'),
  ('Bir öğrenci x² + 3x − 4 = 0 denklemi için Δ = 9 − 16 = −7 bulup denklemin gerçek kökü olmadığını söylüyor. Öğrencinin hatası nedir?', 'c = −4\'ün eksi işaretini hesaba katmamıştır', ['Δ formülünde b yerine 2b yazmıştır', 'Doğru hesaplamıştır, gerçek kök yoktur', 'a\'yı 1 yerine 0 almıştır'], 'Doğru hesap Δ = 9 − 4·1·(−4) = 25\'tir. Denklemin 1 ve −4 olmak üzere iki gerçek kökü vardır.'),
  ('Bir öğrenci 2x² − 6x + 4 = 0 denkleminde kökleri x = 6 ± √4/4 biçiminde hesaplayıp 6,5 ve 5,5 buluyor. Hatası nedir ve doğru kökler hangileridir?', 'Payın tamamını 2a\'ya bölmemiştir; kökler 1 ve 2', ['Δ\'yı yanlış bulmuştur; kökler −1 ve −2', '−b yerine b almıştır; kökler −6,5 ve −5,5', 'Hata yoktur; kökler 6,5 ve 5,5'], 'Kök formülü x = (−b ± √Δ)/2a\'dır; bölme payın tamamına uygulanır: (6 ± 2)/4, yani 2 ve 1.'),
  ('Bir öğrenci (x + 3)² = x² + 9 kabul ederek (x + 3)² = 25 denkleminden x² = 16 ve x = ±4 buluyor. Denklemin doğru çözüm kümesi hangisidir?', '{2, −8}', ['{4, −4}', '{2, 8}', '{−2, 8}'], '(x + 3)² = x² + 6x + 9\'dur; öğrenci 6x terimini atlamıştır. Doğrusu x + 3 = ±5, yani x = 2 veya x = −8\'dir.'),
  ('Bir öğrenci −x² + 4 > 0 eşitsizliğini −1 ile çarpıp x² − 4 > 0 yazıyor ve x < −2 veya x > 2 buluyor. Doğru çözüm hangisidir?', '−2 < x < 2', ['x < −2 veya x > 2', 'x > 2', 'x < 2'], 'Negatif bir sayıyla çarpınca eşitsizlik yön değiştirir: x² − 4 < 0 olmalıydı. Bu da −2 < x < 2 verir.'),
  ('(x − 1)(x − 4) < 0 eşitsizliğini "x − 1 < 0 ve x − 4 < 0" yazarak x < 1 bulan öğrencinin hatası nedir?', 'Negatif çarpım için çarpanlar ters işaretli olmalıdır; doğru çözüm 1 < x < 4', ['Çarpanların ikisi de pozitif olmalıydı; doğru çözüm x > 4', 'Hata yoktur; çözüm x < 1\'dir', 'Eşitsizlik yön değiştirmeliydi; doğru çözüm x > 1'], 'İki çarpanın çarpımı negatifse biri pozitif, diğeri negatiftir. x − 1 > 0 ve x − 4 < 0 birlikte 1 < x < 4 verir.'),
  ('Bir öğrenci x² + 6x = 7 denklemini tam kareye tamamlarken sol tarafı (x + 3)² yapıp sağ tarafı 7 bırakıyor. Hatası nedir ve doğru kökler hangileridir?', 'Sağa da 9 eklemeliydi; kökler 1 ve −7', ['Sola 3 eklemeliydi; kökler 3 ve −3', 'Hata yoktur; kökler −3 ± √7', 'Sağdan 9 çıkarmalıydı; kökler −1 ve 7'], 'Sola eklenen 9 sağa da eklenmelidir: (x + 3)² = 16, x + 3 = ±4, x = 1 veya x = −7.'),
  ('x² − 4x + 1 = 0 denkleminin kökleri için bir öğrenci x₁² + x₂² = (x₁ + x₂)² = 16 yazıyor. Doğru değer ve hata hangisidir?', '14; −2x₁x₂ terimini unutmuştur', ['16; hata yoktur', '18; +2x₁x₂ eklemeyi unutmuştur', '15; kökler çarpımını yanlış almıştır'], 'x₁² + x₂² = (x₁ + x₂)² − 2x₁x₂ = 16 − 2 = 14\'tür.'),
  ('Bir öğrenci x² + x + 1 > 0 eşitsizliği için "Δ < 0 olduğundan eşitsizliğin çözümü yoktur" diyor. Bu yorum için hangisi doğrudur?', 'Yanlıştır; ifade her x için pozitif olduğundan çözüm ℝ\'dir', ['Doğrudur; çözüm kümesi boştur', 'Yanlıştır; çözüm yalnız x > 0\'dır', 'Yanlıştır; çözüm yalnız x = −1/2 dışındaki sayılardır'], 'Δ < 0, denklemin gerçek kökü olmadığını söyler; eşitsizlik için ise ifadenin hiç işaret değiştirmediğini gösterir. a > 0 olduğundan ifade daima pozitiftir.'),
  ('x² − 6x + 2 = 0 eşitliğinin iki çözümü ile bu çözümlerin çarpmaya göre tersleri, dört sayı olarak toplanıyor. Bu dört sayının toplamı kaçtır?', '9', ['6', '3', '12'], 'x₁ + x₂ = 6 ve 1/x₁ + 1/x₂ = (x₁ + x₂)/(x₁x₂) = 6/2 = 3\'tür. Toplam 9 olur.'),
  ('Pozitif iki kökünün aritmetik ortalaması 4, geometrik ortalaması 3 olan ve başkatsayısı 1 olan ikinci dereceden denklem hangisidir?', 'x² − 8x + 9 = 0', ['x² − 4x + 3 = 0', 'x² − 8x + 3 = 0', 'x² − 8x + 12 = 0'], 'Aritmetik ortalama 4 ise kökler toplamı 8, geometrik ortalama 3 ise çarpım 9\'dur. Denklem x² − 8x + 9 = 0 olur.'),
  ('x² − 10x + 16 = 0 denkleminin köklerinin harmonik ortalaması kaçtır?', '16/5', ['5', '4', '8/5'], 'İki sayının harmonik ortalaması 2x₁x₂/(x₁ + x₂)\'dir: 2·16/10 = 16/5. (Kökler 2 ve 8\'dir.)'),
  ('Gerçek kökleri olan ikinci dereceden bir denklemin kökler toplamı da kökler çarpımı da k\'ya eşittir. k hangi koşulu sağlar?', 'k ≤ 0 veya k ≥ 4', ['0 ≤ k ≤ 4', 'k ≥ 4', 'k ≤ −4 veya k ≥ 4'], 'Denklem x² − kx + k = 0 biçimindedir. Gerçek kök için Δ = k² − 4k ≥ 0, yani k(k − 4) ≥ 0 gerekir.'),
  ('a sayısı x² − 3x + 1 = 0 denkleminin sıfırdan farklı bir kökü ise a + 1/a toplamı kaçtır?', '3', ['1', '−3', '9'], 'a² − 3a + 1 = 0 eşitliği a\'ya bölünürse a − 3 + 1/a = 0, yani a + 1/a = 3 olur.'),
  ('x² − 2x + m = 0 denkleminin köklerinden biri −1\'den küçük, diğeri 2\'den büyük olacaksa m hangi koşulu sağlamalıdır?', 'm < −3', ['m < 0', 'm < 1', '−3 < m < 0'], 'Başkatsayı pozitif olduğundan hem −1 hem 2 kökler arasında olmalıdır: f(−1) = 3 + m < 0 ve f(2) = m < 0. İkisinin ortak koşulu m < −3\'tür.'),
  ('x² + 2mx + 4 = 0 denkleminin köklerinden biri 1\'den küçük, diğeri 1\'den büyük olduğuna göre m hangi koşulu sağlar?', 'm < −5/2', ['m > −5/2', 'm < −2', 'm < −5/2 veya m > 2'], 'a = 1 > 0 olduğundan 1\'in kökler arasında olması f(1) < 0 demektir: 1 + 2m + 4 < 0, m < −5/2.'),
  ('x² − 12x + p = 0 denkleminin kökleri pozitif tam sayılardır ve p bir asal sayıdır. p kaçtır?', '11', ['7', '5', '35'], 'Kökler çarpımı asal ise kökler 1 ve p olmalıdır. Toplamları 12 olduğundan p = 11 bulunur.'),
  ('x² − 5x + 6 = 0 ve x² + mx − 3 = 0 denklemlerinin bir ortak kökü vardır. m\'nin alabileceği değerlerin toplamı kaçtır?', '−5/2', ['−2', '−1/2', '5/2'], 'Birinci denklemin kökleri 2 ve 3\'tür. Ortak kök 2 ise 4 + 2m − 3 = 0, m = −1/2; ortak kök 3 ise 9 + 3m − 3 = 0, m = −2 olur. Toplam −5/2\'dir.'),
  ('İki basamaklı bir sayı, rakamları toplamının 4 katına eşittir ve rakamlarının çarpımı 8\'dir. Bu sayı kaçtır?', '24', ['42', '18', '81'], 'Sayı 10a + b ise 10a + b = 4(a + b), yani b = 2a olur. ab = 2a² = 8\'den a = 2, b = 4 bulunur.'),
  ('Ardışık üç pozitif çift sayıdan en büyüğünün karesi, diğer ikisinin karelerinin toplamına eşittir. Bu üç sayının toplamı kaçtır?', '24', ['18', '30', '12'], 'Sayılar x, x + 2, x + 4 ise (x + 4)² = x² + (x + 2)², buradan x² − 4x − 12 = 0 ve pozitif çözüm x = 6 bulunur. Sayılar 6, 8, 10\'dur.'),
  ('Bir küpün her kenarı 1 cm uzatılınca hacmi 19 cm³ artıyor. Küpün ilk kenar uzunluğu kaç cm\'dir?', '2', ['3', '1', '19/3'], '(x + 1)³ − x³ = 3x² + 3x + 1 = 19 eşitliği x² + x − 6 = 0 verir. Pozitif kök x = 2\'dir.'),
  ('Bir fıskiyeden 6 m yükseklikte çıkan suyun izlediği yol y = −0,5x² + 2x + 6 eğrisiyle veriliyor (x yatay uzaklık, metre). Su, çıkış noktasının altındaki zeminden kaç m uzağa düşer?', '6', ['2', '4', '12'], 'Zemine düşünce y = 0\'dır: 0,5x² − 2x − 6 = 0, yani x² − 4x − 12 = 0. Kökler 6 ve −2\'dir; uzaklık 6 m\'dir.'),
  ('Dik kenarlarının uzunlukları toplamı 17 cm ve alanı 30 cm² olan bir dik üçgenin hipotenüsü kaç cm\'dir?', '13', ['12', '15', '√229'], 'a + b = 17 ve ab = 60\'tır. a² + b² = 289 − 120 = 169 olduğundan hipotenüs 13 cm\'dir (kenarlar 5 ve 12).'),
  ('Aynı noktadan aynı anda aynı yöne harekete başlayan iki araçtan biri sabit 20 m/s hızla gider, diğeri durgun hâlden başlayıp t saniyede t² metre yol alır. İkinci araç birinciye kaçıncı saniyede yetişir?', '20', ['10', '40', '√20'], 'Konumlar eşitlenir: t² = 20t. t(t − 20) = 0\'dan t = 0 (başlangıç) veya t = 20 s bulunur.'),
  ('Bir devre elemanına aktarılan güç, I amperlik akımda P = 12I − 2I² watt olarak veriliyor. Gücü 16 W yapan iki farklı akım değerinin toplamı kaçtır?', '6', ['8', '4', '12'], '12I − 2I² = 16 eşitliği I² − 6I + 8 = 0 olur. Akımlar 2 A ve 4 A\'dır; toplamları 6\'dır.'),
  ('Kare biçimli bir fotoğrafın kenarlarının her biri 4 cm kısaltılınca alanı ilk alanın %36\'sına düşüyor. Fotoğrafın ilk kenar uzunluğu kaç cm\'dir?', '10', ['5/2', '6', '16'], '(x − 4)² = 0,36x² ise x − 4 = 0,6x (kenar pozitif olmalı) ve x = 10 bulunur. Diğer çözüm x = 5/2, x − 4\'ü negatif yaptığı için geçersizdir.'),
  ('Kenarları 4 cm ve 6 cm olan bir dikdörtgenin her iki kenarına aynı x uzunluğu eklenince alan iki katına çıkıyor. x kaç cm\'dir?', '2', ['12', '4', '1'], '(4 + x)(6 + x) = 48 eşitliği x² + 10x − 24 = 0 verir. (x − 2)(x + 12) = 0\'dan x = 2 cm\'dir.'),
  ('Bir pozitif sayı ile karekökünün toplamı 20\'dir. Bu sayı kaçtır?', '16', ['25', '4', '20 − √20'], '√x = t ile t² + t − 20 = 0 olur; t = 4 (t ≥ 0). Sayı x = 16\'dır.'),
  ('"Bir sayının karesinden 3 katı çıkarılınca, sayının 5 katının 20 eksiği elde ediliyor." Bu koşulu sağlayan gerçek sayılar için hangisi doğrudur?', 'Böyle bir gerçek sayı yoktur', ['Yalnız 4 sağlar', '2 ve 10 sağlar', 'Yalnız −4 sağlar'], 'x² − 3x = 5x − 20 eşitliği x² − 8x + 20 = 0 olur. Δ = 64 − 80 < 0 olduğundan gerçek çözüm yoktur.'),
  ('x² + bx + c = 0 denkleminin köklerinin her biri 2 artırılarak başkatsayısı 1 olan yeni bir denklem elde ediliyor. Yeni denklemin diskriminantı için hangisi doğrudur?', 'Değişmez', ['4 artar', '2 katına çıkar', '4 azalır'], 'Başkatsayı 1 iken Δ = (x₁ − x₂)²\'dir. Köklerin ikisine de aynı sayı eklenince farkları değişmez, dolayısıyla Δ da aynı kalır.'),
  ('Bir denklemin iki tarafını (x − 3) ifadesiyle çarpmak çözüm kümesini nasıl etkileyebilir?', 'Asıl denklemde olmayan x = 3 kökünü ekleyebilir', ['Her zaman bir kök kaybettirir', 'Çözüm kümesini hiçbir durumda değiştirmez', 'Bütün kökleri 3 artırır'], 'x = 3 için iki taraf da sıfır olacağından yeni denklem bu değeri de sağlar; bu yüzden bulunan kökler asıl denklemde denenmelidir.'),
  ('Gerçek katsayılı ve gerçek kökü olmayan ikinci dereceden bir denklemin iki karmaşık kökünün toplamı için ne söylenebilir?', 'Her zaman bir gerçek sayıdır', ['Her zaman saf sanal bir sayıdır', 'Her zaman sıfırdır', 'Hesaplanamaz'], 'Bu kökler p + qi ve p − qi biçiminde eşlenik çifttir; toplamları 2p = −b/a gerçek bir sayıdır.'),
  ('Katsayıları simetrik olan ax⁴ + bx³ + cx² + bx + a = 0 (a ≠ 0) denkleminin bir kökü r ise aşağıdakilerden hangisi de kesinlikle bir köktür?', '1/r', ['−r', 'r²', '2r'], 'Denklem x⁴\'e bölünüp 1/x yazıldığında aynı denklem elde edilir. Bu yüzden r kök ise 1/r de köktür (r ≠ 0, çünkü a ≠ 0).'),
  ('Katsayıları simetrik olan x³ − 3x² − 3x + 1 = 0 tek dereceli denkleminin kesinlikle kökü olan sayı hangisidir?', '−1', ['1', '3', '0'], 'Tek dereceli simetrik denklemlerde x = −1 her zaman köktür: −1 − 3 + 3 + 1 = 0. Kalan çarpan x² − 4x + 1\'dir.'),
  ('x² − 4x + 1 = 0 denkleminin kökleri (2 + √3 ve 2 − √3) hem birbirinin eşleniği hem de çarpmaya göre tersidir. Bu iki özelliğin birlikte görülmesinin nedeni nedir?', 'Katsayılar rasyoneldir ve sabit terim başkatsayıya eşittir', ['Diskriminant negatiftir', 'Kökler toplamı sıfırdır', 'Başkatsayı negatiftir'], 'Rasyonel katsayılı olduğu için irrasyonel kökler eşlenik çıkar; c = a olduğu için kökler çarpımı c/a = 1 olur ve kökler birbirinin tersidir.'),
  ('İki ikinci derece denklemin iki kökü de ortaktır. Bu denklemlerin katsayıları arasında nasıl bir ilişki vardır?', 'Karşılıklı katsayıları orantılıdır', ['Sabit terimleri eşittir, diğerleri farklıdır', 'Başkatsayıları birbirinin tersidir', 'Hiçbir ilişki yoktur'], 'Kökleri aynı olan iki ikinci derece ifade a(x − x₁)(x − x₂) biçiminde yalnız başkatsayıyla ayrılır; bu yüzden katsayıları orantılıdır.'),
  ('(log x)² − 3·log x + 2 = 0 denklemi log x = t yazılarak çözülüyor (log, 10 tabanlıdır). Denklemi sağlayan x değerleri hangileridir?', '10 ve 100', ['1 ve 2', '2 ve 3', '10 ve 1000'], 't² − 3t + 2 = 0\'dan t = 1 veya t = 2 bulunur. log x = 1 için x = 10, log x = 2 için x = 100\'dür.'),
  ('x² − 2|x − 1| − 1 = 0 denklemi x ≥ 1 ve x < 1 durumlarına ayrılarak çözülüyor. Çözüm kümesi hangisidir?', '{−3, 1}', ['{1}', '{−3, 1, 3}', '{−1, 3}'], 'x ≥ 1 iken x² − 2x + 1 = 0 ve x = 1 bulunur. x < 1 iken x² + 2x − 3 = 0\'dan x = −3 (x = 1 bu durumda alınmaz) çıkar.'),
  ('Payı paydasından küçük olan bir kesrin payı ile paydasının toplamı 9\'dur. Kesir ile çarpmaya göre tersinin toplamı 41/20 olduğuna göre kesir hangisidir?', '4/5', ['5/4', '2/7', '3/6'], 'Pay a ise a/(9 − a) + (9 − a)/a = 41/20 olur ve a = 4 ya da a = 5 bulunur. Pay küçük olacağından kesir 4/5\'tir.'),
  ('Çarpmaya göre tersinin karesi 4\'ten büyük olan x sayıları, yani 1/x² > 4 koşulunu sağlayanlar hangi kümededir?', '(−1/2, 0) ∪ (0, 1/2)', ['(−1/2, 1/2)', '(0, 1/2)', '(−∞, −1/2) ∪ (1/2, ∞)'], 'x ≠ 0 iken x² > 0 olduğundan iki taraf x² ile çarpılabilir: 1 > 4x², yani |x| < 1/2. x = 0 ifadeyi tanımsız yaptığından çıkarılır.'),
  ('x² > 1/x² eşitsizliğini sağlayan gerçek sayılar hangileridir?', '|x| > 1 olan sayılar', ['|x| < 1 olan sayılar', 'Yalnız x > 1 olan sayılar', '0 dışındaki bütün sayılar'], 'x ≠ 0 iken x² ile çarpınca x⁴ > 1, yani x² > 1 bulunur. Bu |x| > 1 demektir.'),
  ('Cardano 1545\'te Ars Magna\'da "10\'u, çarpımları 40 olan iki parçaya ayırma" problemini ele almıştır. Bu problemin çözümünde ortaya çıkan sayılar için hangisi doğrudur?', 'Gerçek değildir; 5 ± √(−15) biçimindedir', ['5 ve 8 tam sayılarıdır', 'Biri pozitif biri negatif gerçek sayıdır', '4 ve 6 sayılarıdır'], 'Parçalar x ve 10 − x ise x² − 10x + 40 = 0 olur; Δ = 100 − 160 < 0\'dır. Cardano bu "olanaksız" kökleri 5 ± √(−15) olarak yazmıştır.'),
  ('Negatif sayıların karekökünü içeren kökler için "sanal (imaginaire)" nitelemesini 1637\'de La Géométrie adlı eserinde kullanan matematikçi kimdir?', 'René Descartes', ['Leonhard Euler', 'Pierre de Fermat', 'Blaise Pascal'], 'Descartes, gerçek olmayan kökleri küçümseyici bir anlamla "imaginaire" diye adlandırmıştır; bugünkü sanal sayı terimi buradan gelir. i simgesini ise daha sonra Euler kullanmıştır.'),
  ('(2x − 1)² = (x + 2)² denklemi a² = b² ⇒ a = b veya a = −b kuralıyla çözülürse hangi kökler bulunur?', '3 ve −1/3', ['3 ve 1/3', '−3 ve 1/3', 'Yalnız 3'], '2x − 1 = x + 2 ise x = 3; 2x − 1 = −(x + 2) ise 3x = −1, x = −1/3 olur.'),
  ('(x + 1)/(x − 1) = 2x/(x + 1) orantısını sağlayan x değerlerinin toplamı kaçtır?', '4', ['2', '−4', '1'], 'İçler dışlar çarpımı (x + 1)² = 2x(x − 1), yani x² − 4x − 1 = 0 verir. Kökler 2 ± √5 paydaları sıfırlamaz; toplamları 4\'tür.'),
  ('İki sayının toplamı 5\'tir; karelerinin toplamından çarpımları çıkarılınca 7 kalıyor. Bu iki sayının çarpımı kaçtır?', '6', ['18', '−6', '4'], 'x² − xy + y² = (x + y)² − 3xy olduğundan 25 − 3xy = 7 ve xy = 6 bulunur.'),
  ('(x − 1)(x − 2) > x − 1 eşitsizliğini iki tarafı x − 1\'e bölmeden çözen birinin bulacağı küme hangisidir?', 'x < 1 veya x > 3', ['x > 3', '1 < x < 3', 'x < 3'], 'Terimler bir tarafa toplanınca (x − 1)(x − 2 − 1) > 0, yani (x − 1)(x − 3) > 0 olur. x − 1\'e bölmek, x < 1 iken yönü değiştireceği için hatalı sonuç verir.'),
  ('x² − 5x + 4 < 0 olduğuna göre |x − 1| + |x − 4| ifadesinin değeri kaçtır?', '3', ['2x − 5', '5 − 2x', '5'], 'Koşul 1 < x < 4 verir. Bu aralıkta x − 1 > 0 ve x − 4 < 0 olduğundan ifade (x − 1) + (4 − x) = 3 olur.'),
  ('x² − 4x + 3 < 0 eşitsizliğinin her çözümü x < m eşitsizliğini de sağlıyor. m\'nin alabileceği en küçük değer kaçtır?', '3', ['1', '4', '2'], 'Birinci eşitsizliğin çözümü (1, 3)\'tür. Bu aralığın tamamının x < m içinde kalması için m ≥ 3 gerekir; en küçük değer 3\'tür.'),
  ('Karekök çarpanı içeren √(x + 2)·(x² − 9) ≤ 0 koşulunu sağlayan x değerlerinin tamamı hangi aralıktadır?', '[−2, 3]', ['[−3, 3]', '(−2, 3]', '(−∞, −3] ∪ [−2, 3]'], 'Tanım için x ≥ −2 gerekir; x = −2\'de çarpım sıfırdır. x > −2 iken karekök pozitif olduğundan x² − 9 ≤ 0, yani x ≤ 3 olmalıdır.'),
  ('a, b, c sıfırdan farklı ve a + b + c = 0\'dır. bx² + cx + a = 0 denkleminin kökleri hangileridir?', '1 ve a/b', ['1 ve b/a', '−1 ve a/b', '1 ve c/b'], 'Katsayılar toplamı b + c + a = 0 olduğundan x = 1 bir köktür. Kökler çarpımı a/b olduğundan diğer kök a/b\'dir.'),
  ('Bir tam kare ile mutlak değerin eşitlendiği x² − 6x + 9 = |x − 3| denkleminin bütün çözümleri toplanınca kaç elde edilir?', '9', ['6', '3', '7'], 'Sol taraf (x − 3)² = |x − 3|²\'dir. |x − 3| = t ile t² = t, yani t = 0 veya t = 1 bulunur. Buradan x = 3, 2, 4 çıkar; toplam 9\'dur.'),
  ('φ altın oran olmak üzere 1/φ + 1/φ² toplamı kaçtır?', '1', ['φ', '2', 'φ − 1'], 'φ² = φ + 1 eşitliği φ²\'ye bölünürse 1 = 1/φ + 1/φ² elde edilir.'),
  ('a ≠ b olmak üzere a² = 5a − 2 ve b² = 5b − 2 eşitlikleri veriliyor. a² + b² toplamı kaçtır?', '21', ['25', '29', '23'], 'a ve b, x² − 5x + 2 = 0 denkleminin iki farklı köküdür. a + b = 5, ab = 2 olduğundan a² + b² = 25 − 4 = 21 bulunur.'),
  ('Boyu eninin 2 katı olan dikdörtgen bir kartonun dört köşesinden kenarı 2 cm olan kareler kesilip kenarlar katlanarak hacmi 96 cm³ olan üstü açık bir kutu yapılıyor. Kartonun eni kaç cm\'dir?', '8', ['6', '12', '16'], 'Eni x ise kutunun tabanı (x − 4) ve (2x − 4), yüksekliği 2\'dir: 2(x − 4)(2x − 4) = 96. Buradan x² − 6x − 16 = 0 ve x = 8 bulunur.'),
  ('Harezmî\'nin cebir kitabında "mâl" (servet) adını verdiği nicelik bugünkü gösterimle hangisidir?', 'x²', ['x', 'Sabit sayı', 'x³'], 'Harezmî bilinmeyene "cizr" (kök), bilinmeyenin karesine "mâl", sabit sayılara ise "dirhem" ya da "aded" demiştir.'),
  ('x² − 2x + m < 0 eşitsizliğini sağlayan en az bir gerçek sayının bulunması için m hangi koşulu sağlamalıdır?', 'm < 1', ['m > 1', 'm ≤ 1', 'm < 0'], 'Başkatsayı pozitif olduğundan ifadenin negatif değer alabilmesi için iki farklı gerçek kök gerekir: Δ = 4 − 4m > 0, yani m < 1. m = 1\'de ifade (x − 1)² olur ve negatif olmaz.'),
  ('Bir köprünün kemer biçimli açıklığının yüksekliği, ortadan x metre uzakta y = 8 − 0,02x² metredir. Yüksekliği 6 m olan bir aracın kemerin altından geçebileceği yatay şeridin toplam genişliği en çok kaç metredir?', '20', ['10', '40', '100'], '8 − 0,02x² ≥ 6 ise x² ≤ 100, yani −10 ≤ x ≤ 10\'dur. Şeridin genişliği 20 m\'dir.'),
  ('Karesi mutlak değerine eşit olan kaç farklı gerçek sayı vardır?', '3', ['2', '4', '1'], '|x| = t ile t² − t = 0, t = 0 veya t = 1 olur. Buradan x = 0, 1, −1 olmak üzere üç kök çıkar.'),
  ('Bir sayı kendi mutlak değeriyle çarpılınca 4 elde ediliyor (x·|x| = 4). Bu koşula uyan sayılar hangileridir?', '{2}', ['{−2, 2}', '{−2}', '{4}'], 'x > 0 iken x² = 4 ve x = 2 bulunur. x < 0 iken −x² = 4 olur ve çözüm yoktur; x = 0 da sağlamaz.'),
  ('(x² − x − 2)/(x − 2) = 3 eşitliğinde sadeleştirme yapılınca bulunan değerin paydayla ilişkisi incelenmelidir. Eşitliği sağlayan x\'lerin kümesi nedir?', '∅', ['{2}', '{−1}', '{2, −1}'], 'x ≠ 2 için kesir x + 1\'e sadeleşir ve x + 1 = 3\'ten x = 2 çıkar. Bu değer paydayı sıfırladığından çözüm yoktur.'),
  ('x⁶ − 9x³ + 8 = 0 eşitliğinde x³ yeni bir bilinmeyen gibi düşünülüyor. Gerçek çözümler toplandığında ne bulunur?', '3', ['9', '1', '2'], 'x³ = t ile t² − 9t + 8 = 0, t = 1 veya t = 8 bulunur. Gerçek sayılarda x³ = 1\'den x = 1, x³ = 8\'den x = 2 çıkar; toplam 3\'tür.'),
  ('x² − 5x + k = 0 denkleminin köklerinin kareleri arasındaki fark 15\'tir. k kaçtır?', '4', ['6', '−4', '5/2'], 'x₁² − x₂² = (x₁ + x₂)(x₁ − x₂) = 5(x₁ − x₂) = 15 olduğundan kökler farkı 3\'tür. (x₁ − x₂)² = 25 − 4k = 9\'dan k = 4 bulunur.'),
  ('Bir otobüs firmasında bilet 50 TL iken 400 yolcu taşınıyor; bilete yapılan her 5 TL\'lik zam 20 yolcu kaybettiriyor. Geliri 21.600 TL yapan iki farklı bilet fiyatının toplamı kaçtır?', '150 TL', ['120 TL', '100 TL', '160 TL'], 'n zam adımı için (50 + 5n)(400 − 20n) = 21.600, yani n² − 10n + 16 = 0 olur. n = 2 veya n = 8; fiyatlar 60 TL ve 90 TL\'dir.'),
  ('Viète, 1591 tarihli çalışmasında bilinmeyen nicelikleri harflerle göstermiştir. Bilinmeyenler için hangi harf grubunu kullanmıştır?', 'Sesli harfleri', ['Sessiz harfleri', 'Yunan harflerini', 'Alfabenin son harflerini'], 'Viète bilinmeyenleri A, E gibi sesli harflerle, bilinen nicelikleri ise B, C, D gibi sessiz harflerle göstermiştir. Son harfleri (x, y, z) kullanma geleneği Descartes\'la yerleşmiştir.'),
  ('x² + 4x + c = 0 denkleminde c\'nin değeri arttıkça kökler hakkında hangisi doğrudur?', 'c > 4 olunca gerçek kökler kaybolur', ['Kökler her c için gerçektir', 'Kökler toplamı da artar', 'c arttıkça kökler arası uzaklık artar'], 'Δ = 16 − 4c olduğundan c büyüdükçe Δ küçülür; c = 4\'te çift kök, c > 4\'te gerçek kök yoktur. Kökler toplamı ise c\'den bağımsız olarak −4\'tür.'),
  ('x pozitif bir gerçek sayıdır ve x² + 1/x² = 14 eşitliği sağlanıyor. x + 1/x ifadesi kaça eşittir?', '4', ['√14', '3', '16'], '(x + 1/x)² = 14 + 2 = 16 olur. x pozitif olduğundan x + 1/x = 4 bulunur.'),
  ('2x² − 5x + 2 = 0 denkleminin iki kökü arasında nasıl bir ilişki vardır?', 'Birbirinin çarpmaya göre tersidir', ['Birbirinin toplamaya göre tersidir', 'Biri diğerinin karesidir', 'Aralarındaki fark 1\'dir'], 'Kökler çarpımı c/a = 1 olduğundan x₁·x₂ = 1 yani kökler 2 ve 1/2\'dir; biri diğerinin çarpmaya göre tersidir.'),
  ('x² − 3x + 1 = 0 denklemini sağlayan x için x³ + 1/x³ ifadesi kaçtır?', '18', ['27', '9', '24'], 'x ≠ 0 olduğundan x + 1/x = 3 bulunur. x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 27 − 9 = 18 olur.'),
  ('x² + 2x + 10 = 0 denkleminin karmaşık kökleri arasında sanal kısmı pozitif olan hangisidir?', '−1 + 3i', ['1 + 3i', '−1 − 3i', '−2 + 3i'], 'Δ = 4 − 40 = −36 olduğundan x = (−2 ± 6i)/2 = −1 ± 3i bulunur. Sanal kısmı pozitif olan −1 + 3i\'dir.'),
  ('x² − 2x + 5 = 0 denkleminin kökleri karmaşık sayılar olarak bulunuyor. Bu iki kökün çarpımı kaçtır?', '5', ['−5', '2', '1'], 'Kökler 1 + 2i ve 1 − 2i\'dir. Çarpım (1 + 2i)(1 − 2i) = 1 + 4 = 5 olur; bu değer c/a ile de uyuşur.'),
  ('x² − 4x + 13 = 0 denkleminin karmaşık köklerinin gerçel kısmı kaçtır?', '2', ['−2', '3', '4'], 'Δ = 16 − 52 = −36 olduğundan x = (4 ± 6i)/2 = 2 ± 3i bulunur. Gerçel kısım 2\'dir.'),
  ('x² − mx + 8 = 0 ile x² − 6x + n = 0 denklemlerinin ortak kökü 4 olduğuna göre m + n toplamı kaçtır?', '14', ['12', '10', '16'], 'x = 4\'ü birinci denklemde yerine koyunca 16 − 4m + 8 = 0 ve m = 6 olur. İkincide 16 − 24 + n = 0 ve n = 8 bulunur; m + n = 14.'),
  ('x² − 4x + 3 = 0 ve x² − 6x + 5 = 0 denklemlerinin ortak olmayan köklerinin toplamı kaçtır?', '8', ['9', '4', '18'], 'Kökler {1, 3} ve {1, 5}\'tir. Ortak kök 1\'dir; ortak olmayanlar 3 ve 5, toplamları 8\'dir.'),
  ('mx² − (m + 2)x + 2 = 0 denkleminin m\'nin hangi değeri için olursa olsun sağladığı sabit kök kaçtır?', '1', ['2', 'm', '−1'], 'x = 1 için m − (m + 2) + 2 = 0 olur ve m\'den bağımsız sağlanır. Öteki kök çarpımdan 2/m bulunur.'),
  ('x² − 5x + 3 = 0 denkleminin kökleri a ve b olduğuna göre kökleri a² ve b² olan başkatsayısı 1 olan denklem hangisidir?', 'x² − 19x + 9 = 0', ['x² − 25x + 9 = 0', 'x² − 19x + 3 = 0', 'x² + 19x + 9 = 0'], 'a² + b² = 25 − 2·3 = 19 ve a²b² = 3² = 9 bulunur. Denklem x² − 19x + 9 = 0 olur.'),
  ('x² − 4x + 1 = 0 denkleminin kökleri x₁ ve x₂ olduğuna göre, bu köklerin birbirine oranlarının toplamı olan x₁/x₂ + x₂/x₁ kaçtır?', '14', ['16', '12', '15'], 'x₁² + x₂² = 16 − 2 = 14 ve x₁x₂ = 1 olduğundan toplam 14/1 = 14 bulunur.'),
  ('Bir havuzu birinci musluk tek başına x saatte, ikinci musluk ise x + 3 saatte dolduruyor. İkisi birlikte açıldığında havuz 2 saatte doluyorsa birinci musluk tek başına havuzu kaç saatte doldurur?', '3', ['2', '4', '13'], 'Birlikte 1/x + 1/(x + 3) = 1/2 olur. Düzenlenince x² − x − 6 = 0 ve pozitif kök x = 3 bulunur.'),
  ('Bir ürünün fiyatı art arda iki kez aynı yüzde oranında indiriliyor ve 100 TL\'lik ürün 64 TL\'ye düşüyor. Her indirimin oranı yüzde kaçtır?', '20', ['18', '25', '36'], '100(1 − r)² = 64 olduğundan 1 − r = 0,8 ve r = 0,2 bulunur; her indirim yüzde 20\'dir.'),
  ('Bir dikdörtgenin uzun kenarı kısa kenarından 7 cm fazladır ve köşegeni 13 cm\'dir. Bu dikdörtgenin çevresi kaç cm\'dir?', '34', ['30', '36', '115'], 'Kısa kenar a ise a² + (a + 7)² = 169 olur ve a² + 7a − 60 = 0 denkleminden a = 5 bulunur. Kenarlar 5 ve 12 olduğundan çevre 34\'tür.'),
  ('Dik kenar uzunlukları ardışık çift sayılar, hipotenüsü 10 cm olan dik üçgenin alanı kaç cm²\'dir?', '24', ['12', '30', '48'], 'Dik kenarlar x ve x + 2 ise x² + (x + 2)² = 100 olur ve x = 6 bulunur. Alan 6·8/2 = 24 olur.'),
  ('Pozitif bir sayı ile çarpmaya göre tersinin toplamı 13/6 ise bu sayının büyük olanı kaçtır?', '3/2', ['2', '3', '13/6'], 'x + 1/x = 13/6 ise 6x² − 13x + 6 = 0 olur; kökler 3/2 ve 2/3\'tür. Büyük olan 3/2\'dir.'),
  ('Bir top yerden 25 m yükseklikten h(t) = −5t² + 20t + 25 (metre) kuralına göre atılıyor. Top 40 m yüksekliğe ilk kez kaçıncı saniyede ulaşır?', '1', ['2', '3', '11'], '−5t² + 20t + 25 = 40 denkleminden t² − 4t + 3 = 0 ve t = 1 ya da t = 3 bulunur. İlk ulaşma anı t = 1 saniyedir.'),
  ('Her takımın diğer takımlarla evinde ve deplasmanda olmak üzere ikişer maç yaptığı bir ligde toplam 30 maç oynanıyor. Ligde kaç takım vardır?', '6', ['5', '7', '15'], 'n takım için maç sayısı n(n − 1) = 30 olur. n² − n − 30 = 0 denkleminden n = 6 bulunur.'),
  ('Dikdörtgen biçimindeki bir havuzun çevresine eşit genişlikte bir kaldırım yapılıyor. Havuz 8×6 m, kaldırımlı toplam alan 120 m² ise kaldırım genişliği kaç m\'dir?', '2', ['1', '3', '1,5'], '(8 + 2x)(6 + 2x) = 120 ise 4x² + 28x − 72 = 0, yani x² + 7x − 18 = 0 ve x = 2 bulunur.'),
  ('Toplamları 20, kareleri toplamı 232 olan iki pozitif sayıdan küçük olanı kaçtır?', '6', ['4', '8', '10'], 'Çarpım (400 − 232)/2 = 84 olur. Sayılar t² − 20t + 84 = 0 denkleminin kökleridir: 6 ve 14.'),
  ('x² − 4x ≥ 0 ve x² < 9 koşullarının ikisini birlikte sağlayan kaç tam sayı vardır?', '3', ['2', '5', '12'], 'Birinci koşuldan x ≤ 0 veya x ≥ 4, ikinciden −3 < x < 3 gelir. Ortak küme (−3, 0] olup tam sayılar −2, −1 ve 0\'dır.'),
  ('|x² − 4| < 5 eşitsizliğini sağlayan tam sayıların sayısı kaçtır?', '5', ['4', '7', '11'], '−5 < x² − 4 < 5 ise −1 < x² < 9 olur ve x² ≥ 0 her zaman sağlanır. Bu yüzden x² < 9, yani −3 < x < 3 ve tam sayılar −2, −1, 0, 1, 2\'dir.'),
  ('Pay ve paydasının köklerini işaret tablosunda gösterip yorumlayınız: (x² − 1)/(x − 3) ≥ 0 koşulunu sağlayan x değerleri hangi birleşim kümesidir?', '[−1, 1] ∪ (3, ∞)', ['(−∞, −1] ∪ [1, 3)', '[−1, 1] ∪ [3, ∞)', '(−1, 1) ∪ (3, ∞)'], 'Kritik noktalar −1, 1 ve 3\'tür; işaret tablosu +∞ tarafından − , +, −, + biçimindedir. Pay kökleri dahil, payda kökü 3 hariç tutulur.'),
  ('Çözüm kümesi (−∞, −1] ∪ [4, ∞) olan x² + bx + c ≥ 0 eşitsizliğinde b + c toplamı kaçtır?', '−7', ['7', '−1', '−12'], 'Kökler −1 ve 4 olduğundan x² − 3x − 4 ≥ 0 olur. b = −3, c = −4 ve b + c = −7\'dir.'),
  ('x² + bx + c < 0 eşitsizliğinin çözüm kümesi (1, 3) aralığı ise b·c çarpımı kaçtır?', '−12', ['12', '−4', '3'], 'Kökler 1 ve 3 olduğundan x² − 4x + 3 < 0 olur. b = −4, c = 3 ve b·c = −12 bulunur.'),
  ('Bir cisim h(t) = −5t² + 30t (metre) kuralına göre yukarı fırlatılıyor. Cisim 40 metrenin üzerinde kaç saniye kalır?', '2', ['3', '4', '12'], '−5t² + 30t > 40 ise t² − 6t + 8 < 0 olur ve 2 < t < 4 bulunur. Süre 4 − 2 = 2 saniyedir.'),
  ('Paydası aynı olan iki kesrin farkını 1\'e eşitleyen x/(x − 3) − 2/(x − 3) = 1 denklemi için hangi sonuç doğrudur?', 'Boş kümedir', ['{2}', '{3}', 'Tüm gerçek sayılar'], 'Pay (x − 2)/(x − 3) = 1 olur; x ≠ 3 iken x − 2 = x − 3 çelişkisine ulaşılır. Denklemin çözümü yoktur.'),
  ('1/(x − 2) + 1/(x + 2) = 3/(x² − 4) denkleminin kökü kaçtır?', '3/2', ['2', '−2', '3'], 'Paydalar eşitlenince 2x/(x² − 4) = 3/(x² − 4) olur ve x ≠ ±2 iken 2x = 3\'ten x = 3/2 bulunur.'),
  ('Karekök ifadesini yalnız bırakıp iki tarafın karesini alan bir öğrenci √(x + 7) − 1 = x denkleminde sınama yapmayı unutuyor. Sınama yapıldıktan sonra kalan kök kümesi hangisidir?', '{2}', ['{−3, 2}', '{−3}', '{1, 2}'], '√(x + 7) = x + 1 ifadesinin karesinden x² + x − 6 = 0 ve x = 2 veya x = −3 çıkar. x = −3 için x + 1 = −2 negatif olduğundan yabancı köktür.'),
  ('Kök içindeki ifadenin tam kare olduğu √(x² − 4x + 4) = 3 eşitliğinde bulunan bütün değerleri toplarsak sonuç ne olur?', '4', ['−4', '6', '−1'], 'Kök içi (x − 2)² olduğundan |x − 2| = 3 elde edilir. Kökler 5 ve −1\'dir; toplam 4\'tür.'),
  ('Mutlak değer içinde ikinci dereceden bir ifade bulunan |x² − 1| = 3 eşitliğini iki ayrı durumda inceleyiniz. Kaç farklı gerçel çözüm elde edilir?', '2', ['1', '3', '12'], 'x² − 1 = 3 ise x = ±2; x² − 1 = −3 ise x² = −2 olup gerçek kök vermez. Denklemin iki kökü vardır.'),
  ('f(x) = 2x² − 12x + 7 fonksiyonu tam kare biçiminde yazıldığında en küçük değeri kaç olur?', '−11', ['−18', '7', '−5'], 'f(x) = 2(x² − 6x) + 7 = 2(x − 3)² − 18 + 7 = 2(x − 3)² − 11 olur. En küçük değer −11\'dir.'),
  ('x² − 5x + m = 0 denkleminin köklerinden biri 1\'den küçük, diğeri 1\'den büyüktür. Bu bilgiye göre m için ne söylenebilir?', 'm < 4', ['m > 4', 'm < 25/4', 'm > 6'], 'Başkatsayı pozitif olduğundan 1 iki kökün arasında kalacaksa f(1) < 0 olmalıdır: 1 − 5 + m < 0 ve m < 4 bulunur.'),
  ('x² − 5x + k = 0 denkleminin kökleri pozitif tam sayı olacak biçimde k\'nin alabileceği değerler toplanırsa sonuç kaç olur?', '10', ['6', '4', '24'], 'Toplamı 5 olan pozitif tam sayı kökler (1, 4) ve (2, 3) olup k = 4 veya k = 6\'dır. Toplam 10 bulunur.'),
  ('x² − (a + 2)x + 2a = 0 denkleminin a\'nın alacağı her gerçek değer için sağladığı sabit kök hangisidir?', '2', ['a', '−2', '0'], 'Denklem (x − 2)(x − a) = 0 biçiminde çarpanlanır; bu yüzden x = 2 her a değeri için köktür.'),
  ('x² − 6x + 7 = 0 denkleminin iki kökü arasındaki farkın mutlak değeri kaçtır?', '2√2', ['√2', '4', '√8 + 1'], 'Δ = 36 − 28 = 8 olduğundan kökler 3 ± √2\'dir. Fark |x₁ − x₂| = √Δ/a = 2√2 bulunur.'),
  ('Rasyonel katsayılı x² + bx + c = 0 denkleminin köklerinden biri 1 + √5 ise b + c toplamı kaçtır?', '−6', ['6', '−2', '−4'], 'Diğer kök eşlenik olan 1 − √5\'tir. Toplam 2 ve çarpım −4 olduğundan b = −2, c = −4 ve b + c = −6 olur.'),
  ('kx² − 4x − 1 = 0 denkleminin hiç gerçek kökü olmaması için k\'nin alabileceği en büyük tam sayı değeri kaçtır?', '−5', ['−4', '−3', '5'], 'Δ = 16 + 4k < 0 olmalıdır; bu da k < −4 verir. En büyük tam sayı −5\'tir.'),
  ('Toplamları 6, kareleri toplamı 20 olan iki gerçek sayının küpleri toplamı kaçtır?', '72', ['56', '48', '216'], '(x + y)² = 36 olduğundan 2xy = 16 ve xy = 8 bulunur. x³ + y³ = (x + y)(x² − xy + y²) = 6·12 = 72\'dir.'),
  ('Bilinmeyenin mutlak değeri üzerinden kurulan x² − 4|x| − 5 = 0 denkleminde, gerçek sayı çözümleri birbiriyle çarpıldığında hangi sonuç bulunur?', '−25', ['25', '5', '−5'], '|x| = t dersek t² − 4t − 5 = 0 ve t = 5 (t = −1 olamaz) bulunur. Kökler 5 ve −5 olduğundan çarpım −25\'tir.'),
  ('Üslü ifadelerden oluşan 2²ˣ − 5·2ˣ + 4 = 0 eşitliğinde, 2ˣ yerine yeni bir değişken yazılarak bulunan x çözümleri toplanırsa sonuç ne olur?', '2', ['5', '4', '12'], '2ˣ = t alınırsa t² − 5t + 4 = 0 ve t = 1 veya t = 4 olur. Buradan x = 0 ve x = 2 bulunur; toplam 2\'dir.'),
  ('Karekök içeren x − 5√x + 6 = 0 eşitliğinde √x = t denilerek elde edilen çözümlerden x değerleri bulunup toplanırsa sonuç ne olur?', '13', ['5', '6', '25'], '√x = t alınınca t² − 5t + 6 = 0 ve t = 2 veya t = 3 olur. x = 4 ve x = 9 bulunur; toplam 13\'tür.'),
  ('(m − 1)x² − 2x + 1 > 0 eşitsizliğinin her gerçek sayı için sağlanması isteniyor. Bu durumda m parametresi hangi koşulu sağlamalıdır?', 'm > 2', ['m > 1 olması yeterlidir', 'm < 2 olmalıdır', '1 < m < 2 aralığında olmalıdır'], 'Parabolün kolları yukarı olmalı: m − 1 > 0. Ayrıca Δ = 4 − 4(m − 1) < 0 ile m > 2 gelir; ortak koşul m > 2\'dir.'),
  ('x² + 2mx + 4 ≥ 0 eşitsizliği her gerçek x değeri için doğru olacaksa m\'nin alabileceği tam sayı değerlerinin sayısı kaçtır?', '5', ['3', '4', '15'], 'Başkatsayı pozitif olduğundan Δ ≤ 0 yeterlidir: 4m² − 16 ≤ 0 ise −2 ≤ m ≤ 2. Tam sayılar −2, −1, 0, 1, 2 olduğundan 5 tanedir.'),
  ('(x − 1)(x − 2)(x − 3) > 0 eşitsizliğini sağlayan ve 0 ile 10 arasında (uçlar dahil) bulunan tam sayılar kaç tanedir?', '7', ['6', '5', '10'], 'Çözüm kümesi (1, 2) ∪ (3, ∞) olup tam sayı içermeyen bir aralık ile devam eder. 0 ≤ x ≤ 10 için 4, 5, ..., 10 olmak üzere 7 tam sayı vardır.'),
  ('Çift katlı bir kök içeren (x + 1)²(x − 5) < 0 çarpımının negatif olduğu bölgede yer alan, sıfırdan büyük kaç tane tamsayı bulunur?', '4', ['5', '3', '14'], '(x + 1)² ≥ 0 olduğundan x − 5 < 0 olmalı ve x = −1 hariç tutulmalıdır. Pozitif tam sayılar 1, 2, 3, 4 olur.'),
  ('Paydası hiçbir gerçek sayıda sıfır olmayan (2 − x)(x + 4)/(x² + 1) kesri negatif olmayan değerler aldığında, bu tamsayı çözümlerin toplamı hangisidir?', '−7', ['−9', '0', '7'], 'Payda her zaman pozitiftir, bu yüzden (2 − x)(x + 4) ≥ 0 ve −4 ≤ x ≤ 2 olmalıdır. −4 + (−3) + (−2) + (−1) + 0 + 1 + 2 = −7 bulunur.'),
  ('Paydası iki farklı kökü olan bir kesir verilmiştir. Kesrin kesinlikle pozitif olduğu x/(x² − 4) durumunda gerçek sayı aralıkları hangi birleşimdir?', '(−2, 0) ∪ (2, ∞)', ['(−∞, −2) ∪ (0, 2)', '(−2, 2)', '(2, ∞) ve ayrıca x = 0'], 'Kritik noktalar −2, 0 ve 2\'dir. İşaret sağdan sola +, −, +, − olduğundan x/(x² − 4) pozitifliği (−2, 0) ile (2, ∞) aralıklarında sağlanır.'),
  ('Bir sayının karesinin kendi mutlak değerinden büyük olması isteniyor. Bu istek hangi gerçek sayılar tarafından karşılanır?', '(−∞, −1) ∪', ['(−1, 1) kümesinden 0 çıkarılmış hali', '(1, ∞) aralığının tamamı', 'ℝ − {0}'], '|x|² > |x| ise |x|(|x| − 1) > 0 olur; x = 0 değil ve |x| > 1 gereklidir. Çözüm x < −1 veya x > 1\'dir.'),
  ('Mutlak değerli ifadenin sağ taraftaki doğrusal ifadeden küçük olduğu |2x − 1| < x + 1 durumunda, çözüm aralığına düşen tamsayıların adedi nedir?', '1', ['0', '2', '11'], '−(x + 1) < 2x − 1 < x + 1 ise 0 < x < 2 bulunur. Bu aralıktaki tek tam sayı 1\'dir.'),
  ('Mutlak değer ve karenin birlikte yer aldığı x² − |x| − 6 < 0 koşulunda çözüm kümesine ait tamsayıların adedi kaçtır?', '5', ['3', '7', '15'], '|x| = t için t² − t − 6 < 0 ve t ≥ 0 olduğundan 0 ≤ t < 3 elde edilir. −3 < x < 3 olup tam sayılar −2, −1, 0, 1, 2\'dir.'),
  ('Bir öğrenci (x − 1)(x − 4) > 0 eşitsizliğinde x − 1 > 0 ve x − 4 > 0 yazıp çözüm olarak x > 4 buluyor. Öğrencinin hatası nedir?', 'İki çarpanın da negatif olduğu durumu atlamıştır', ['Eşitsizliğin yönünü değiştirmesi gerekirdi', 'Eşitsizliği önce sıfıra eşitleyip kökleri bulmalıydı', 'Çarpanlardan birini diğerinin işaretine göre çevirmeliydi'], 'Çarpım pozitifse çarpanlar aynı işaretlidir: ikisi de pozitif (x > 4) ya da ikisi de negatif (x < 1) olabilir. Doğru çözüm x < 1 veya x > 4\'tür.'),
  ('Aşağıdaki eşitsizliklerden hangisinin gerçek sayılardaki çözüm kümesi yalnızca {2} tek elemanlı kümesidir?', '−x² + 4x − 4 ≥ 0', ['x² − 4x + 4 ≥ 0', 'x² − 4x + 4 > 0', 'x² − 4x + 4 < 0'], '−x² + 4x − 4 = −(x − 2)² olduğundan ≥ 0 koşulu yalnız x = 2 için sağlanır. Diğer seçeneklerin çözüm kümeleri ℝ, ℝ − {2} ve boş kümedir.'),
  ('x² − mx + 12 = 0 denkleminin kökleri pozitif tam sayılar ise m\'nin alabileceği en küçük değer kaçtır?', '7', ['8', '13', '4'], 'Çarpımı 12 olan pozitif tam sayı çiftleri (1, 12), (2, 6), (3, 4) olup toplamlar 13, 8 ve 7\'dir. En küçük m = 7\'dir.'),
  ('İşaret tablosu çizerek, üç farklı kökü bulunan (x² − 4)(x − 1) çarpımının sıfır ya da pozitif olduğu aralıkların birleşimini belirleyiniz.', '[−2, 1] ∪ [2, ∞)', ['(−∞, −2] ∪ [1, 2]', '[−2, 2] ∪ [1, ∞)', '[−2, 1) ∪'], 'Kökler −2, 1 ve 2\'dir; sağdan başlayarak işaret +, −, +, − olur. Pozitif bölgeler ve kökler birleştirilince [−2, 1] ∪ [2, ∞) bulunur.'),
];
